maha_emit_menu() {
  cat <<'MAHA_MENU_7c1a'
#!/data/data/com.termux/files/usr/bin/bash
# maha-commute, the launcher. Written by the installer.
#
# Midnight Commander, and the debt is deliberate. What is lifted is not the
# look, it is the way mc lets a pair of panels share one set of keys.
#
# FOUR QUADRANTS, one app each. A quadrant is empty when its app is not
# running and empty when there is no app for it at all: the fourth is free
# and stays drawn, because a slot that appears when a fourth app arrives is
# a screen that moves under the hand. Nothing appears, nothing disappears.
#
#   +-----------------+-----------------+
#   | 1 day.commute   | 2 night.commute |
#   +-----------------+-----------------+
#   | 3 all.commute   | 4 free          |
#   +-----------------+-----------------+
#
# 1 2 3 4 FILL a quadrant. An empty quadrant is an app that is not running,
# so pressing its number starts that server and the quadrant fills in front
# of you. Pressing the number of a quadrant that is already filled opens its
# page again. The number means one thing in both cases: put me in this app.
#
# The label is drawn whether the quadrant is filled or not, so the number
# never has to be looked up. 1 is always day.commute, on this phone and on
# every other one.
#
# THE VERBS ARE THE SAME FOR EVERY QUADRANT and they act on the focused one.
# That is the whole point: one set of keys, learned once, and the only thing
# that changes is which app is listening.
#
#   Enter  open it, starting it first if it is not running
#   o      open the page again, for when the tab was closed
#   s      stop it
#   R      restart it
#   l      its log, the last twenty lines in its own words
#   i      install it, or remove it if it is here
#
# SERVERS STACK. Starting one does not take the terminal and does not stop
# another. All three can run at once: they hold 8082, 8087 and 8084.
#
# The bottom row is the things that belong to no single app, and it is
# always the same ten slots in the same order, dim when they do not apply.

. "$HOME/.maha.commute/env.sh" 2>/dev/null || {
  printf 'maha-commute: ~/.maha.commute/env.sh is missing.\n'
  printf 'Run the installer again.\n'; exit 1; }

if [ -t 1 ]; then
  AM="\033[38;5;214m"; SAND="\033[38;5;223m"; OK="\033[1;32m"
  BAD="\033[1;31m"; KEY="\033[1;37m"; DIM="\033[0;90m"
  BAR="\033[48;5;24m\033[1;37m"; OFF="\033[0m"
else
  AM=""; SAND=""; OK=""; BAD=""; KEY=""; DIM=""; BAR=""; OFF=""
fi

RUNDIR="$APPHOME/running"; mkdir -p "$RUNDIR"
# One id per launcher session. The page compares it with the one it stored
# and clears what you picked when they differ, which is what makes a new
# run start clean instead of where you left off.
RUN=$(date +%s)
PY="$(command -v python3 || command -v python)"
SEL=1
LAST=""

STTY_SAVED=""
restore_tty() { [ -n "$STTY_SAVED" ] && stty "$STTY_SAVED" 2>/dev/null || true; }
trap 'restore_tty' EXIT INT TERM HUP
STTY_SAVED=$(stty -g 2>/dev/null || true)

field()   { printf '%s' "$1" | cut -d'|' -f"$2"; }
app_row() { printf '%s\n' "$MAHA_APPS" | grep "^$1|" || true; }
app_ids() { printf '%s\n' "$MAHA_APPS" | cut -d'|' -f1; }
app_at()  { app_ids | sed -n "${1}p"; }
n_apps()  { app_ids | wc -l | tr -d ' '; }

is_installed() { local c; c=$(field "$(app_row "$1")" 2); [ -n "$c" ] && [ -x "$BIN/$c" ]; }
stamped()      { if [ -f "$STAMPDIR/$1" ]; then tr -d ' \n' < "$STAMPDIR/$1"; else printf '?'; fi; }
# A plain connect in a subshell, which is what v1 shipped and what Test 1
# exercises. The "hardened" version wrapped this in `timeout 1 bash -c` and
# that is what hung the panel: the wrapper child inherits the terminal, and
# killing the wrapper does not always close what it left open. A deadline
# that introduces a process is not a deadline, it is another thing to wait
# for. Connect only, never read, so there is nothing to wait on.
port_live() {
  (exec 3<>"/dev/tcp/127.0.0.1/$1") 2>/dev/null && exec 3<&- && return 0
  return 1
}

# The process first, the socket second, because asking the process table is
# local and cannot block on anything. pgrep is not everywhere, so ps is the
# fallback rather than an assumption: without this the socket probe is on
# the hot path of every redraw.
proc_alive() {
  if command -v pgrep >/dev/null 2>&1; then
    pgrep -f "$1" >/dev/null 2>&1
  else
    ps -eo args 2>/dev/null | grep -v grep | grep -qF "$1"
  fi
}

# The port an app actually bound, which is not always the one it wanted:
# each of the three walks forward when its first choice is busy. The file
# the server writes is the truth; the table is only the fallback.
app_port() {
  local row dir p
  row=$(app_row "$1"); dir="$HOME/$(field "$row" 3)"
  # The file is tested before it is read. A redirection from a file that is
  # not there is bash's error to print, not the command's to swallow, so
  # 2>/dev/null on the read does not stop it landing in the middle of the
  # frame. Checking first is the only thing that does.
  p=""
  [ -f "$dir/port" ] && p=$(tr -d ' \n' < "$dir/port" 2>/dev/null)
  if [ -n "$p" ]; then printf '%s' "$p"; else field "$row" 5; fi
}

running() {
  local proc; proc=$(field "$(app_row "$1")" 7)
  proc_alive "$proc" && return 0
  port_live "$(app_port "$1")"
}

# am first, and its OUTPUT read rather than its exit code, because asking
# for a package that is not installed prints an error and still exits zero.
open_url() {
  local url="$1" out pkg
  for pkg in com.android.chrome com.chrome.beta com.chrome.dev; do
    out=$(am start -a android.intent.action.VIEW -d "$url" -p "$pkg" 2>&1)
    case "$out" in
      *rror*|*xception*|*"not found"*|*"unable to resolve"*) : ;;
      *) return 0 ;;
    esac
  done
  command -v termux-open-url >/dev/null 2>&1 && { termux-open-url "$url"; return 0; }
  command -v xdg-open >/dev/null 2>&1 && { xdg-open "$url" >/dev/null 2>&1; return 0; }
  command -v open >/dev/null 2>&1 && { open "$url" >/dev/null 2>&1; return 0; }
  printf "  %s\n" "$url"
}

anykey() {
  printf "\n  ${DIM}%s${OFF} " "${1:-any key}"
  read -rsn1 _x 2>/dev/null || read -r _x
  printf "\n"
}

offer_install() {
  local id="$1" cmd a; cmd=$(field "$(app_row "$id")" 2)
  printf "\n  ${SAND}%s is not installed.${OFF}\n" "$cmd"
  printf "  ${DIM}its payload is already here, so this needs no download${OFF}\n"
  printf "\n  ${KEY}Enter${OFF} ${DIM}install${OFF}   ${KEY}n${OFF} ${DIM}leave it${OFF}\n\n  ${AM}>${OFF} "
  IFS= read -r a || a="n"
  case "$a" in [nN]*) return 0 ;; esac
  bash "$APPHOME/install-one.sh" "$id" --offline || true
  anykey
}

start_app() {
  local id="$1" cmd port i last shown=""
  cmd=$(field "$(app_row "$id")" 2)
  if ! is_installed "$id"; then offer_install "$id"; return; fi
  if running "$id"; then LAST="$id"; open_url "http://127.0.0.1:$(app_port "$id")/?run=$RUN"; return; fi

  printf "\n  ${DIM}starting %s${OFF}\n" "$cmd"

  # setsid and </dev/null. The app gets its own session and no terminal, so
  # it cannot compete with this menu for a keypress and it does not die when
  # the menu is quit. Inheriting the terminal is how a backgrounded server
  # ends up eating the key you pressed for something else.
  ( cd "$HOME" && setsid nohup "$BIN/$cmd" </dev/null > "$RUNDIR/$id.log" 2>&1 &
    echo $! > "$RUNDIR/$id.pid" ) 2>/dev/null ||
  ( cd "$HOME" && nohup "$BIN/$cmd" </dev/null > "$RUNDIR/$id.log" 2>&1 &
    echo $! > "$RUNDIR/$id.pid" )

  # A FIRST start is not a restart. day.commute fetches an eleven megabyte
  # schedule from ZET and builds its caches before it binds anything, which
  # on a phone on mobile data is minutes. The old wait here was sixteen
  # seconds, so it announced failure while the app was still working, and
  # the app opened its own browser tab in the meantime. That is the whole
  # bug: a tab with nothing behind it yet, and a menu saying it did not
  # come up.
  #
  # So the wait is long, it says how long it has been, it shows the app's
  # own last line, and a keypress leaves it running rather than killing it.
  printf "  ${DIM}first start builds the schedule, this can take minutes${OFF}\n"
  printf "  ${DIM}any key to leave it working and go back${OFF}\n\n"
  for i in $(seq 1 450); do
    running "$id" && break
    if [ $((i % 5)) = 0 ]; then
      last=$(tail -1 "$RUNDIR/$id.log" 2>/dev/null | tr -d '\r' | sed 's/\x1b\[[0-9;]*[A-Za-z]//g' | cut -c1-40)
      [ -n "$last" ] && [ "$last" != "$shown" ] && { printf "  ${DIM}%s${OFF}\n" "$last"; shown="$last"; }
      printf "\r  ${AM}%ss${OFF}${DIM} waiting for port %s${OFF}   " "$((i * 2 / 5))" "$(app_port "$id")"
    fi
    # A key means stop waiting, not stop the app.
    if read -rsn1 -t 0.4 _k 2>/dev/null; then
      printf "\n\n  ${SAND}left working in the background.${OFF}\n"
      printf "  ${DIM}the quadrant fills when it answers${OFF}\n"
      sleep 1; return
    fi
  done
  printf "\r                                                  \r"

  if running "$id"; then
    port=$(app_port "$id"); LAST="$id"
    printf "  ${OK}up${OFF} ${DIM}on %s${OFF}\n" "$port"
    open_url "http://127.0.0.1:$port/?run=$RUN"
    sleep 1
  else
    printf "  ${BAD}%s has not answered in three minutes${OFF}\n" "$cmd"
    printf "  ${DIM}it may still be working. Its own words:${OFF}\n\n"
    tail -6 "$RUNDIR/$id.log" 2>/dev/null | sed 's/^/    /'
    printf "\n  ${DIM}%s${OFF}\n" "$RUNDIR/$id.log"
    anykey
  fi
}

stop_app() {
  local id="$1" cmd proc
  cmd=$(field "$(app_row "$id")" 2); proc=$(field "$(app_row "$id")" 7)
  if ! running "$id"; then printf "  ${DIM}%s is not running${OFF}\n" "$cmd"; return; fi
  # Its own launcher first where it has a stop verb, because it knows what
  # else it started. Then the process name, for the ones that do not.
  grep -q '^  stop)' "$BIN/$cmd" 2>/dev/null && "$BIN/$cmd" stop >/dev/null 2>&1
  pkill -f "$proc" 2>/dev/null
  [ -f "$RUNDIR/$id.pid" ] && kill "$(cat "$RUNDIR/$id.pid")" 2>/dev/null
  rm -f "$RUNDIR/$id.pid"
  sleep 1
  if running "$id"; then
    printf "  ${BAD}%s would not stop${OFF}\n" "$cmd"
  else
    printf "  ${OK}%s stopped${OFF}\n" "$cmd"
    [ "$LAST" = "$id" ] && LAST=""
  fi
}

stop_all() {
  printf "\n"
  local id any=0
  for id in $(app_ids); do running "$id" && { stop_app "$id"; any=1; }; done
  [ "$any" = 0 ] && printf "  ${DIM}nothing was running${OFF}\n"
  anykey
}

# ---------------------------------------------------------------
# the grid
#
# Four quadrants, two by two, one app each. A quadrant that holds no app
# is drawn empty rather than left out, because the grid is the map: the
# fourth is where the next app goes, and its frame being there already is
# what makes that true rather than a plan.
#
# 1 2 3 4 move the focus. The focused quadrant is lit and EVERY command
# below acts on it. The commands do not change from one app to the next,
# on purpose: the same key does the same thing whichever quadrant is lit,
# so the fingers learn it once. That is worth more than giving each app
# its own clever key.
#
# Colour is padded AFTER the string is sized. printf counts an escape
# sequence as characters, so colouring first and padding second makes
# every coloured cell nine columns narrower than its neighbour, and the
# frame stops being a frame.
# ---------------------------------------------------------------
CW=22

pad() { printf '%-*.*s' "$CW" "$CW" "$1"; }

cell_lines() {
  # Three lines for one quadrant, plain text, into L1 L2 L3.
  local n="$1" id row cmd ver
  id=$(app_at "$n")
  if [ -z "$id" ]; then
    L1=" $n  free"; L2="   for the next app"; L3=""; CQ="dim"; return
  fi
  row=$(app_row "$id"); cmd=$(field "$row" 2)
  if ! is_installed "$id"; then
    L1=" $n $cmd"; L2="   not installed"; L3="   i puts it here"; CQ="dim"
  elif running "$id"; then
    ver=$(stamped "$id")
    L1=" $n $cmd"
    L2="   running  $(app_port "$id")"
    if [ "$LAST" = "$id" ]; then L3="   $ver  last opened"; else L3="   $ver"; fi
    CQ="ok"
  else
    L1=" $n $cmd"; L2="   ready"; L3="   $(stamped "$id")"; CQ="sand"
  fi
}

paint() {
  case "$1" in
    ok)   printf '%b%s%b' "$OK" "$2" "$OFF" ;;
    sand) printf '%b%s%b' "$SAND" "$2" "$OFF" ;;
    dim)  printf '%b%s%b' "$DIM" "$2" "$OFF" ;;
    bar)  printf '%b%s%b' "$BAR" "$2" "$OFF" ;;
    *)    printf '%s' "$2" ;;
  esac
}

row_pair() {
  # Two quadrants side by side. Left is $1, right is $2.
  local a="$1" b="$2" al1 al2 al3 ac bl1 bl2 bl3 bc
  cell_lines "$a"; al1=$(pad "$L1"); al2=$(pad "$L2"); al3=$(pad "$L3"); ac="$CQ"
  cell_lines "$b"; bl1=$(pad "$L1"); bl2=$(pad "$L2"); bl3=$(pad "$L3"); bc="$CQ"
  local at="$ac" bt="$bc"
  [ "$FOCUS" = "$a" ] && at="bar"
  [ "$FOCUS" = "$b" ] && bt="bar"
  printf "  ${AM}|${OFF}%s${AM}|${OFF}%s${AM}|${OFF}\n" "$(paint "$at" "$al1")" "$(paint "$bt" "$bl1")"
  printf "  ${AM}|${OFF}%s${AM}|${OFF}%s${AM}|${OFF}\n" "$(paint "$ac" "$al2")" "$(paint "$bc" "$bl2")"
  printf "  ${AM}|${OFF}%s${AM}|${OFF}%s${AM}|${OFF}\n" "$(paint "$ac" "$al3")" "$(paint "$bc" "$bl3")"
}

rule() { printf "  ${AM}+----------------------+----------------------+${OFF}\n"; }

fkey() {
  if [ "$4" = 1 ]; then
    printf "${DIM}%s${OFF}${KEY}%s${OFF}${SAND}%-7s${OFF}" "$1" "$2" "$3"
  else
    printf "${DIM}%s%s%-7s${OFF}" "$1" "$2" "$3"
  fi
}

W=21   # inner width of one quadrant, so two of them plus the rules fit a
       # phone terminal at about fifty columns. Measured, not guessed.

# Padding is done on the PLAIN text and the colour wrapped around it
# afterwards. printf counts the bytes of an escape sequence as width, so a
# coloured string handed to %-21s comes out short by exactly the length of
# the escapes, and every rule on the right hand side walks left.
pad() { printf "%-${W}.${W}s" "$1"; }

uptime_of() {
  local id="$1" pidf="$RUNDIR/$1.pid" s
  [ -f "$pidf" ] || { printf ''; return; }
  s=$(( $(date +%s) - $(date -r "$pidf" +%s 2>/dev/null || date +%s) ))
  if   [ "$s" -lt 60 ];   then printf '%ds' "$s"
  elif [ "$s" -lt 3600 ]; then printf '%dm' "$((s/60))"
  else printf '%dh' "$((s/3600))"; fi
}

# One quadrant's three lines, as plain text, into q1 q2 q3.
cell() {
  local slot="$1" id cmd
  id=$(app_at "$slot")
  if [ -z "$id" ]; then
    q1=$(printf '%d free' "$slot"); q2=''; q3='room for a fourth'
    qstate='empty'; return
  fi
  cmd=$(field "$(app_row "$id")" 2)
  q1=$(printf '%d %s' "$slot" "$cmd")
  q3=$(field "$(app_row "$id")" 8)
  if ! is_installed "$id"; then
    q2='not installed'; qstate='absent'
  elif running "$id"; then
    q2=$(printf '%s  %s  %s' "$(stamped "$id")" "$(app_port "$id")" "$(uptime_of "$id")")
    qstate='running'
  else
    q2=$(printf '%s  ready' "$(stamped "$id")")
    qstate='ready'
  fi
}

# A quadrant is drawn by its state and by whether it has the focus. Colour
# carries the state and nothing else: green is running, sand is installed
# and idle, grey is not here. The focus is a bar, which is a different
# channel, so the two can be read at once.
paint() {
  local text="$1" state="$2" focused="$3"
  if [ "$focused" = 1 ]; then printf "${BAR}%s${OFF}" "$(pad "$text")"; return; fi
  case "$state" in
    running) printf "${OK}%s${OFF}" "$(pad "$text")" ;;
    ready)   printf "${SAND}%s${OFF}" "$(pad "$text")" ;;
    *)       printf "${DIM}%s${OFF}" "$(pad "$text")" ;;
  esac
}

rule() { printf "  ${AM}+"; printf -- '-%.0s' $(seq 1 $W); printf "+"; printf -- '-%.0s' $(seq 1 $W); printf "+${OFF}\n"; }

quad_row() {
  local left="$1" right="$2" l1 l2 l3 r1 r2 r3 ls rs lf rf
  cell "$left";  l1="$q1"; l2="$q2"; l3="$q3"; ls="$qstate"
  cell "$right"; r1="$q1"; r2="$q2"; r3="$q3"; rs="$qstate"
  lf=0; rf=0
  [ "$SEL" = "$left" ] && lf=1
  [ "$SEL" = "$right" ] && rf=1
  printf "  ${AM}|${OFF}%b${AM}|${OFF}%b${AM}|${OFF}\n" \
    "$(paint "$l1" "$ls" "$lf")" "$(paint "$r1" "$rs" "$rf")"
  printf "  ${AM}|${OFF}${DIM}%s${OFF}${AM}|${OFF}${DIM}%s${OFF}${AM}|${OFF}\n" \
    "$(pad "  $l2")" "$(pad "  $r2")"
  printf "  ${AM}|${OFF}${DIM}%s${OFF}${AM}|${OFF}${DIM}%s${OFF}${AM}|${OFF}\n" \
    "$(pad "  $l3")" "$(pad "  $r3")"
}

draw() {
  clear 2>/dev/null || true
  local id any_run=0 sel_id sel_run=0 sel_inst=0
  printf "\n  ${KEY}MAHA COMMUTE${OFF} ${DIM}%s${OFF}\n" "$MAHA_VERSION"
  rule; quad_row 1 2; rule; quad_row 3 4; rule

  sel_id=$(app_at "$SEL")
  [ -n "$sel_id" ] && { running "$sel_id" && sel_run=1; is_installed "$sel_id" && sel_inst=1; }
  for id in $(app_ids); do running "$id" && any_run=1; done

  # The verbs, which act on whichever quadrant has the focus.
  if [ -z "$sel_id" ]; then
    printf "  ${DIM}quadrant 4 is free. The verbs wait for an app.${OFF}\n\n"
  else
    printf "  ${DIM}on ${OFF}${KEY}%s${OFF}${DIM}:${OFF}  " "$(field "$(app_row "$sel_id")" 2)"
    if [ "$sel_inst" != 1 ]; then
      printf "${KEY}Enter${OFF}${SAND}=install${OFF}${DIM}  open stop restart log${OFF}"
    elif [ "$sel_run" = 1 ]; then
      printf "${KEY}Enter${OFF}${SAND}=open${OFF}  ${KEY}s${OFF}${SAND}top${OFF}  ${KEY}R${OFF}${SAND}estart${OFF}  ${KEY}l${OFF}${SAND}og${OFF}"
    else
      printf "${KEY}Enter${OFF}${SAND}=start${OFF}${DIM}  stop restart${OFF}  ${KEY}l${OFF}${SAND}og${OFF}"
    fi
    printf "\n\n"
  fi
  # Every label is spelled by its own key: r efresh, c heck, w ipe. A key
  # whose letter does not begin its word has to be read rather than
  # recognised, and this row is meant to be recognised.
  printf "  "; fkey 1 h "elp" 1; fkey 2 r "efresh" 1; fkey 3 c "heck" 1
  fkey 4 t "est" 1; fkey 5 i "nstall" 1; printf "\n  "
  fkey 6 u "pdate" 1; fkey 7 k "ey" 1; fkey 8 S "topAll" "$any_run"
  fkey 9 w "ipe" 1; fkey 0 q "uit" 1; printf "\n"
  printf "\n  ${DIM}1 2 3 4 fill a quadrant, arrows move without starting${OFF}\n"
  printf "  ${AM}>${OFF} "
}

screen_log() {
  local id="$1" f="$RUNDIR/$1.log"
  clear 2>/dev/null || true
  printf "\n  ${KEY}%s${OFF} ${DIM}in its own words${OFF}\n\n" "$(field "$(app_row "$id")" 2)"
  if [ -s "$f" ]; then
    tail -20 "$f" | cut -c1-46 | sed 's/^/  /'
  else
    printf "  ${DIM}nothing yet. It writes here when it is started from${OFF}\n"
    printf "  ${DIM}this launcher.${OFF}\n"
  fi
  anykey
}

# The panel says what is running. This says what is HERE: where each app
# keeps its data, how big it has grown, whether the payloads still match
# their checksums and whether a key is stored. It reads the disk and the
# local ports and nothing else.
screen_info() {
  local id row cmd dir port
  printf "\n  ${KEY}WHAT IS ON THIS PHONE${OFF}\n\n"
  for id in $(app_ids); do
    row=$(app_row "$id"); cmd=$(field "$row" 2)
    dir="$HOME/$(field "$row" 3)"; port=$(app_port "$id")
    printf "  ${SAND}%s${OFF}\n" "$cmd"
    if is_installed "$id"; then
      printf "    ${DIM}command  ${OFF}${OK}%s${OFF}\n" "$BIN/$cmd"
    else
      printf "    ${DIM}command  not installed${OFF}\n"
    fi
    if [ -d "$dir" ]; then
      printf "    ${DIM}data     %s, %s${OFF}\n" "$dir" "$(du -sh "$dir" 2>/dev/null | cut -f1)"
    else
      printf "    ${DIM}data     none yet${OFF}\n"
    fi
    if port_live "$port"; then
      printf "    ${DIM}port     ${OFF}${OK}%s answering${OFF}\n" "$port"
    else
      printf "    ${DIM}port     %s quiet${OFF}\n" "$port"
    fi
  done
  printf "\n  ${SAND}the umbrella${OFF}\n"
  printf "    ${DIM}payloads %s${OFF}\n" "$PAYDIR"
  if command -v sha256sum >/dev/null 2>&1 && [ -f "$PAYDIR/SHA256SUMS" ]; then
    if ( cd "$PAYDIR" && sha256sum -c --status SHA256SUMS 2>/dev/null ); then
      printf "    ${DIM}checked  ${OFF}${OK}all three match${OFF}\n"
    else
      printf "    ${DIM}checked  ${OFF}${BAD}a payload does not match its checksum${OFF}\n"
    fi
  else
    printf "    ${DIM}checked  no sha256sum here, sizes only${OFF}\n"
  fi
  if [ -s "$KEYFILE" ]; then
    printf "    ${DIM}key      present, %s characters${OFF}\n" \
      "$(tr -d ' \r\n' < "$KEYFILE" | wc -c | tr -d ' ')"
  else
    printf "    ${DIM}key      none${OFF}\n"
  fi
  printf "\n"
}

screen_help() {
  clear 2>/dev/null || true
  cat <<'HELPTEXT'

  MAHA COMMUTE

  Four quadrants, one app each. The fourth is free and stays
  drawn, so the screen does not move when a fourth app arrives.

  1 2 3 4 fill a quadrant. An empty quadrant is a server that
  is not running, so its number starts it and the quadrant
  fills. If it is already filled, the number opens its page.

  Arrows move between quadrants without starting anything,
  for when you want to look before you press.

  The verbs are the same for every quadrant and act on the
  focused one, which is the whole point: one set of keys.

      Enter  open it, starting it first if it is not running
      o      open the page again
      s      stop it
      R      restart it
      l      its log, the last twenty lines
      i      install it, or remove it if it is here

  Servers stack: start all three and all three keep running,
  on 8082, 8087 and 8084.

  The bottom row is always the same ten keys, dim when they do
  not apply. Press the letter. The number is only there because
  a phone has no F keys.

      h  this
      r  refresh every ZET stream, then check it
      c  check the streams without refreshing
      t  test every key this phone holds
      i  install or remove an app
      u  update from a newer installer file
      k  the shared google key
      S  stop all of them
      x  uninstall, which asks twice
      q  quit the menu, leaving the servers running

  Quitting does not stop anything. The servers keep serving and
  the pages stay open. S is what stops them.

HELPTEXT
  anykey
}

screen_install() {
  local id a cmd n
  while :; do
    clear 2>/dev/null || true
    printf "\n  ${KEY}INSTALL OR REMOVE${OFF}\n"
    printf "  ${DIM}a number adds it if missing, takes it away if here${OFF}\n\n"
    n=0
    for id in $(app_ids); do
      n=$((n+1))
      if is_installed "$id"; then
        printf "  ${KEY}%s${OFF}  ${OK}[x]${OFF} ${SAND}%-15s${OFF} ${DIM}%s${OFF}\n" \
          "$n" "$(field "$(app_row "$id")" 2)" "$(stamped "$id")"
      else
        printf "  ${KEY}%s${OFF}  ${DIM}[ ] %-15s not installed${OFF}\n" \
          "$n" "$(field "$(app_row "$id")" 2)"
      fi
    done
    printf "\n  ${KEY}a${OFF} ${DIM}all three${OFF}   ${KEY}q${OFF} ${DIM}back${OFF}\n\n  ${AM}>${OFF} "
    read -rsn1 a 2>/dev/null || read -r a
    printf "\n"
    case "$a" in
      1|2|3)
        id=$(app_at "$a")
        if is_installed "$id"; then
          running "$id" && stop_app "$id"
          cmd=$(field "$(app_row "$id")" 2)
          rm -f "$BIN/$cmd" "$STAMPDIR/$id"
          printf "  ${SAND}%s removed. Its data is untouched.${OFF}\n" "$cmd"
          anykey
        else
          bash "$APPHOME/install-one.sh" "$id" --offline || true; anykey
        fi ;;
      a|A) for id in $(app_ids); do
             is_installed "$id" || bash "$APPHOME/install-one.sh" "$id" --offline || true
           done; anykey ;;
      q|Q|"") return 0 ;;
    esac
  done
}

screen_key() {
  local a k
  clear 2>/dev/null || true
  printf "\n  ${KEY}GOOGLE KEY${OFF}\n"
  printf "  ${DIM}one key, shared by all three, never printed${OFF}\n\n"
  if [ -s "$KEYFILE" ]; then
    printf "  ${OK}present${OFF} ${DIM}%s characters${OFF}\n" \
      "$(tr -d ' \r\n' < "$KEYFILE" | wc -c | tr -d ' ')"
  else
    printf "  ${DIM}none stored${OFF}\n"
  fi
  printf "\n  ${KEY}Enter${OFF} ${DIM}back${OFF}  ${KEY}p${OFF} ${DIM}paste one${OFF}  ${KEY}x${OFF} ${DIM}forget it${OFF}\n\n  ${AM}>${OFF} "
  IFS= read -r a || a=""
  case "$a" in
    p|P) printf "\n  ${DIM}paste, then Enter${OFF}\n  ${AM}>${OFF} "
         IFS= read -r k || k=""
         k=$(printf '%s' "$k" | tr -cd 'A-Za-z0-9_.-' | head -c 200)
         if [ -n "$k" ]; then
           mkdir -p "$KEYDIR"; printf '%s\n' "$k" > "$KEYFILE"; chmod 600 "$KEYFILE"
           printf "\n  ${OK}stored${OFF}\n"
         else
           printf "\n  ${DIM}nothing was changed${OFF}\n"
         fi
         anykey ;;
    x|X) rm -f "$KEYFILE"; printf "\n  ${SAND}forgotten here${OFF}\n"; anykey ;;
  esac
}

case "${1:-}" in
  day|night|all)  start_app "$1"; exit 0 ;;
  stop)           if [ -n "${2:-}" ]; then stop_app "$2"; else stop_all; fi; exit 0 ;;
  # status draws the panel once and leaves. It asks the disk and the local
  # ports and nothing else: a question about what is installed must never
  # reach the network. This case was lost in a rewrite once, which turned
  # `maha-commute status` into an interactive session reading from whatever
  # stdin happened to be, so it is tested now rather than trusted.
  status)         draw; printf "\n"; exit 0 ;;
  info)           screen_info; exit 0 ;;
  install|add)    screen_install; exit 0 ;;
  key)            screen_key; exit 0 ;;
  keytest|keys)   exec "$PY" "$APPHOME/keytest.py" ;;
  refresh)        exec "$PY" "$APPHOME/stream.py" refresh --check ;;
  check|doctor)   exec "$PY" "$APPHOME/stream.py" check ;;
  update)         exec bash "$APPHOME/update.sh" ;;
  uninstall|wipe) exec bash "$APPHOME/uninstall.sh" ;;
  -h|--help)
    printf 'maha-commute [day|night|all|status|info|stop [app]|install|key|keytest|refresh|check|update|uninstall]\n'
    exit 0 ;;
esac

FOCUS=1
while :; do
  draw
  # End of input is not a keypress. Reading EOF used to leave c empty, which
  # matched the Enter case and started an app, so piping anything into the
  # launcher launched something. EOF means the person is gone: leave.
  if ! read -rsn1 c 2>/dev/null; then
    if ! read -r c 2>/dev/null; then printf "\n\n"; exit 0; fi
  fi
  # An arrow arrives as escape, bracket, letter. The two extra reads carry a
  # timeout so Escape on its own does not hang here waiting for the rest of
  # a sequence that is never coming.
  if [ "$c" = "$(printf '\033')" ]; then
    read -rsn1 -t 0.05 c2 2>/dev/null || c2=""
    read -rsn1 -t 0.05 c3 2>/dev/null || c3=""
    case "$c2$c3" in
      "[A"|"[D") c="prev" ;; "[B"|"[C") c="next" ;; *) c="esc" ;;
    esac
  fi
  SELAPP=$(app_at "$SEL")
  case "$c" in
    # A number goes to its quadrant AND fills it. An empty quadrant is a
    # server that is not running, so pressing its number starts it; a
    # quadrant that is already filled opens its page again. One meaning for
    # the number, whatever state the quadrant is in: put me in this app.
    1|2|3|4)
      SEL="$c"
      NEW=$(app_at "$SEL")
      [ -n "$NEW" ] && start_app "$NEW" ;;
    prev) SEL=$((SEL-1)); [ "$SEL" -lt 1 ] && SEL=4 ;;
    next) SEL=$((SEL+1)); [ "$SEL" -gt 4 ] && SEL=1 ;;

    # the verbs, on the focused quadrant
    "")  [ -n "$SELAPP" ] && start_app "$SELAPP" ;;
    o|O) [ -n "$SELAPP" ] && { if running "$SELAPP"; then
           LAST="$SELAPP"; open_url "http://127.0.0.1:$(app_port "$SELAPP")/?run=$RUN"
         else start_app "$SELAPP"; fi; } ;;
    s)   [ -n "$SELAPP" ] && { printf "\n"; stop_app "$SELAPP"; sleep 1; } ;;
    R)   [ -n "$SELAPP" ] && { printf "\n"; stop_app "$SELAPP"; start_app "$SELAPP"; } ;;
    l|L) [ -n "$SELAPP" ] && screen_log "$SELAPP" ;;

    # the things that belong to no single app
    h|H) screen_help ;;
    r)   printf "\n"; "$PY" "$APPHOME/stream.py" refresh --check; anykey ;;
    c|C|d|D) printf "\n"; "$PY" "$APPHOME/stream.py" check; anykey ;;
    t|T) printf "\n"; "$PY" "$APPHOME/keytest.py"; anykey ;;
    i|I) screen_install ;;
    k|K) screen_key ;;
    u|U) printf "\n"; bash "$APPHOME/update.sh"; anykey ;;
    S)   stop_all ;;
    w|W|x|X) printf "\n"; bash "$APPHOME/uninstall.sh"; anykey ;;
    q|Q) printf "\n"
         for id in $(app_ids); do
           running "$id" && { printf "  ${DIM}servers left running. S stops them.${OFF}\n"; break; }
         done
         printf "\n"; exit 0 ;;
  esac
done
MAHA_MENU_7c1a
}

maha_emit_install_one() {
  cat <<'MAHA_INSTALLONE_7c1a'
#!/data/data/com.termux/files/usr/bin/bash
# install-one.sh, written by the MAHA COMMUTE installer.
#
# One app, from the payload already on the phone. This is the only
# routine that installs anything: the installer calls it for each app
# picked on the first run, and the commute menu calls the same file
# when an app is added later. Two callers, one implementation, so a
# fix to the install path cannot reach one of them and miss the other.
#
#   install-one.sh day --offline
#   install-one.sh night --online

set -e
. "$HOME/.maha.commute/env.sh"

APP="${1:-}"
FLAG="${2:---offline}"

if [ -t 1 ]; then
  AM="\033[38;5;214m"; OK="\033[1;32m"; BAD="\033[1;31m"
  DIM="\033[0;90m"; KEY="\033[1;37m"; OFF="\033[0m"
else
  AM=""; OK=""; BAD=""; DIM=""; KEY=""; OFF=""
fi

row=$(printf '%s\n' "$MAHA_APPS" | grep "^$APP|" || true)
if [ -z "$row" ]; then
  printf "  ${BAD}no such app: %s${OFF}\n" "$APP"; exit 2
fi
CMD=$(printf '%s' "$row" | cut -d'|' -f2)
VER=$(printf '%s' "$row" | cut -d'|' -f4)
PORT=$(printf '%s' "$row" | cut -d'|' -f5)
PROC=$(printf '%s' "$row" | cut -d'|' -f7)
SRC="$PAYDIR/$APP.payload.sh"

if [ ! -f "$SRC" ]; then
  printf "  ${BAD}the payload for %s is not on this phone${OFF}\n" "$APP"
  printf "  ${DIM}run the installer again to put it back${OFF}\n"
  exit 3
fi

# Check the payload before running it, not after. A payload that lost
# bytes somewhere installs half an app and says nothing.
if command -v sha256sum >/dev/null 2>&1 && [ -f "$PAYDIR/SHA256SUMS" ]; then
  if ! ( cd "$PAYDIR" && grep " $APP.payload.sh\$" SHA256SUMS | sha256sum -c --status - ); then
    printf "  ${BAD}the %s payload does not match its checksum${OFF}\n" "$APP"
    printf "  ${DIM}nothing was changed${OFF}\n"
    exit 4
  fi
else
  want=$(grep "^$APP|" "$PAYDIR/SIZES" 2>/dev/null | cut -d'|' -f2)
  have=$(wc -c < "$SRC" | tr -d ' ')
  if [ -n "$want" ] && [ "$want" != "$have" ]; then
    printf "  ${BAD}the %s payload is %s bytes, expected %s${OFF}\n" "$APP" "$have" "$want"
    printf "  ${DIM}nothing was changed${OFF}\n"
    exit 4
  fi
fi

# night.commute v9 begins by deleting its own app directory, so an
# upgrade takes everything in it with it. That is the payload's own
# decision and it is left alone: a clean directory is what stops stale
# state, and the umbrella does not get to overrule an app about its own
# data. What the umbrella can do is make it recoverable, so the payload
# is read first and a copy taken only when it is going to wipe.
APPDIR="$HOME/$(printf '%s' "$row" | cut -d'|' -f3)"
if [ -d "$APPDIR" ] && grep -qF "rm -rf \"\$HOME/$(printf '%s' "$row" | cut -d'|' -f3)\"" "$SRC"; then
  BK="$APPHOME/backup/$APP.prev"
  mkdir -p "$APPHOME/backup"
  rm -rf "$BK" 2>/dev/null || true
  if cp -a "$APPDIR" "$BK" 2>/dev/null; then
    printf "  ${DIM}%s clears its folder on install. A copy is kept in${OFF}\n" "$CMD"
    printf "  ${DIM}%s  (%s)${OFF}\n" "$BK" "$(du -sh "$BK" 2>/dev/null | cut -f1)"
  else
    printf "  ${BAD}could not copy %s, and this install will clear it${OFF}\n" "$APPDIR"
    printf "  ${DIM}nothing was changed${OFF}\n"
    exit 5
  fi
fi

mkdir -p "$APPHOME/tmp"
chmod 700 "$APPHOME/tmp" 2>/dev/null || true
TMP="$APPHOME/tmp/$APP.run.sh"
trap 'rm -f "$TMP"' EXIT INT TERM HUP

# Cleaned again here, at the point of use, because the file could have
# been edited by hand between being written and being read.
GKEY=""
if [ -f "$KEYFILE" ]; then
  GKEY=$(grep -v '^[[:space:]]*$' "$KEYFILE" | head -1 | tr -cd 'A-Za-z0-9_-' | head -c 200)
fi

# The key goes into the copy that runs and never into the copy that is
# kept. The kept payload holds a placeholder and nothing else, which is
# why this file can sit in a repository.
{
  head -1 "$SRC"
  printf 'clear() { :; }\n'
  tail -n +2 "$SRC" | sed "s|__MAHA_GOOGLE_KEY__|$GKEY|g"
} > "$TMP"
chmod 600 "$TMP"

printf "\n  ${AM}|${OFF} ${KEY}%s${OFF} ${DIM}%s${OFF}\n" "$CMD" "$VER"

# A server already running is holding the old code in memory, and it
# goes on serving that code after its files have been replaced. From
# outside that looks like an install that did nothing. So it is stopped
# first, by its own launcher where the launcher knows how, and by the
# name of its process where it does not.
if [ -x "$BIN/$CMD" ] && (exec 3<>"/dev/tcp/127.0.0.1/$PORT") 2>/dev/null; then
  exec 3<&-
  printf "  ${DIM}stopping the running server first${OFF}\n"
  if grep -q '^  stop)' "$BIN/$CMD" 2>/dev/null; then
    "$BIN/$CMD" stop >/dev/null 2>&1 || true
  fi
  pkill -f "$PROC" 2>/dev/null || true
  sleep 1
fi

rc=0
bash "$TMP" "$FLAG" || rc=$?
rm -f "$TMP"

if [ "$rc" != "0" ]; then
  printf "  ${BAD}%s did not finish, exit %s${OFF}\n" "$CMD" "$rc"
  exit "$rc"
fi

mkdir -p "$STAMPDIR"
printf '%s\n' "$VER" > "$STAMPDIR/$APP"
exit 0
MAHA_INSTALLONE_7c1a
}

maha_emit_stream() {
  cat <<'MAHA_STREAM_7c1a'
#!/usr/bin/env python3
"""stream.py, written by the MAHA COMMUTE installer.

Two jobs, one file, shared by all three apps because all three drink from
the same two ZET taps:

    the static schedule    https://www.zet.hr/gtfs-scheduled/latest   a zip
    the live feed          https://zet.hr/gtfs-rt-protobuf            protobuf

    python stream.py check     say whether what is arriving is sound
    python stream.py refresh   throw the cached copies away
    python stream.py refresh --check   both, in that order

WHY THIS EXISTS

An app that asks "did the download work" gets yes, and shows old data with
total confidence. Every one of the three apps checks the transport and none
of them checks the CARGO. A feed can be:

    stalled       200 OK, right size, right shape, and a header timestamp
                  from forty minutes ago. This is the common one and it is
                  invisible without reading that timestamp
    thin          200 OK and eleven vehicles in a city that runs six hundred
    disagreeing   live trip ids that are not in the static build the app is
                  holding, because ZET published a new schedule and the app
                  is a day behind. The field does not fit the timetable
    expired       a static build whose calendar ended before today
    misplaced     vehicles at 0,0 or in the Adriatic
    skewed        nothing wrong with the feed at all, the phone's clock is out

Each of those is a different fault with a different fix, and from inside the
app they all look the same: wrong numbers on the screen. So each is measured
separately and named separately.

Nothing here writes to any app's folder except to delete a cache. It never
touches a key, a station index, a stored timetable or a note.
"""

import json
import os
import struct
import sys
import time
import zipfile

APPHOME = os.path.join(os.path.expanduser("~"), ".maha.commute")
RT_URL = "https://zet.hr/gtfs-rt-protobuf"
STATIC_URL = "https://www.zet.hr/gtfs-scheduled/latest"
UA = "maha.commute-stream/1"

# Zagreb, generously. A vehicle outside this is not a vehicle.
LAT_MIN, LAT_MAX = 45.60, 46.05
LON_MIN, LON_MAX = 15.65, 16.30

# What may be deleted, per app. An allowlist and not a wildcard, because a
# refresh that also takes the station index or the stored timetables costs
# an hour of rebuilding and looks like the refresh broke the app.
CACHES = {
    "day": {
        "dir": ".commute",
        "files": ["zet_gtfs.zip", "bus.json", "trips_path.json", "gtfs_meta.json"],
        "dirs": ["daycache"],
        "keep": ["google-api.txt", "gemini-api.txt", "settings.json", "port",
                 "server.log", "pinned.txt"],
    },
    "night": {
        "dir": ".nightcommute",
        "files": ["zet_gtfs.zip"],
        "dirs": [],
        "keep": ["gmaps-api.txt", "gemini-api.txt", "port", "server.out"],
    },
    "all": {
        "dir": ".all.commute",
        "files": ["zet_gtfs.zip"],
        "dirs": [],
        "keep": ["google-api.txt", "gemini-api.txt", "stations.json",
                 "timetables", "all.html", "all_commute_server.py", "port"],
    },
}

STATE = os.path.join(APPHOME, "stream_state.json")


# ---------------------------------------------------------------------------
# a protobuf reader that reads only what it needs
#
# GTFS realtime is protobuf, and the phone has no protobuf library. Only
# three things are wanted: the header timestamp, how many entities there
# are, and the trip id and position inside each one. Wire types are enough
# for that: every field carries its own type, so an unknown field is
# skipped by length rather than guessed at.
# ---------------------------------------------------------------------------

def _varint(b, i):
    shift = 0
    val = 0
    while i < len(b):
        c = b[i]
        val |= (c & 0x7F) << shift
        i += 1
        if not c & 0x80:
            return val, i
        shift += 7
        if shift > 70:
            raise ValueError("varint too long")
    raise ValueError("varint ran off the end")


def _fields(b, start=0, end=None):
    """Yield (field_number, wire_type, value_or_slice) across one message."""
    i = start
    end = len(b) if end is None else end
    while i < end:
        key, i = _varint(b, i)
        fn, wt = key >> 3, key & 7
        if wt == 0:
            v, i = _varint(b, i)
            yield fn, wt, v
        elif wt == 1:
            v = b[i:i + 8]
            i += 8
            yield fn, wt, v
        elif wt == 2:
            ln, i = _varint(b, i)
            if i + ln > end:
                raise ValueError("length delimited field runs past the end")
            yield fn, wt, b[i:i + ln]
            i += ln
        elif wt == 5:
            v = b[i:i + 4]
            i += 4
            yield fn, wt, v
        else:
            raise ValueError("wire type %d, which this feed should not contain" % wt)


def parse_feed(b):
    """FeedMessage -> a small dictionary. Raises on anything malformed."""
    out = {"header_ts": None, "version": None, "entities": 0,
           "trip_ids": [], "positions": [], "entity_ts": []}
    for fn, wt, v in _fields(b):
        if fn == 1 and wt == 2:                      # FeedHeader
            for hfn, hwt, hv in _fields(v):
                if hfn == 1 and hwt == 2:
                    out["version"] = hv.decode("utf-8", "replace")
                elif hfn == 3 and hwt == 0:
                    out["header_ts"] = hv
        elif fn == 2 and wt == 2:                    # FeedEntity
            out["entities"] += 1
            _entity(v, out)
    return out


def _entity(b, out):
    for fn, wt, v in _fields(b):
        if wt != 2:
            continue
        if fn in (3, 4):                             # TripUpdate, VehiclePosition
            for sfn, swt, sv in _fields(v):
                if sfn == 1 and swt == 2:            # TripDescriptor
                    for tfn, twt, tv in _fields(sv):
                        if tfn == 1 and twt == 2:
                            out["trip_ids"].append(tv.decode("utf-8", "replace"))
                elif fn == 4 and sfn == 2 and swt == 2:   # Position
                    lat = lon = None
                    for pfn, pwt, pv in _fields(sv):
                        if pfn == 1 and pwt == 5:
                            lat = struct.unpack("<f", pv)[0]
                        elif pfn == 2 and pwt == 5:
                            lon = struct.unpack("<f", pv)[0]
                    if lat is not None and lon is not None:
                        out["positions"].append((lat, lon))
                elif swt == 0 and sfn in (4, 5):     # a timestamp on the entity
                    if sv > 1000000000:
                        out["entity_ts"].append(sv)


# ---------------------------------------------------------------------------
# the checks
# ---------------------------------------------------------------------------

class Result(list):
    def add(self, level, name, detail):
        self.append((level, name, detail))

    @property
    def bad(self):
        return sum(1 for lvl, _, _ in self if lvl == "bad")

    @property
    def warn(self):
        return sum(1 for lvl, _, _ in self if lvl == "warn")


def _get(url, timeout=20):
    import urllib.request
    req = urllib.request.Request(url, headers={"User-Agent": UA})
    t0 = time.time()
    with urllib.request.urlopen(req, timeout=timeout) as r:
        body = r.read()
        # Lower cased on the way out. dict(r.headers) keeps the server's own
        # capitalisation and a plain dict lookup is case sensitive, so
        # headers.get("Content-Type") came back None against the real feed
        # and the "is this an HTML error page" check would never have fired.
        # A check that cannot fire looks exactly like a check that passes.
        heads = {k.lower(): v for k, v in r.headers.items()}
        return body, r.status, heads, time.time() - t0


def _state():
    try:
        with open(STATE, encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def _save_state(s):
    os.makedirs(APPHOME, exist_ok=True)
    tmp = STATE + ".new"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(s, f)
    os.replace(tmp, STATE)


def check_live(res, state):
    """The live feed: does it arrive, is it fresh, is it moving, does it fit."""
    try:
        body, status, headers, took = _get(RT_URL)
    except Exception as e:
        res.add("bad", "live feed", "did not answer: %s" % e)
        return None
    ctype = headers.get("content-type", "")
    res.add("ok", "live feed answered", "%d, %d bytes, %.1fs" % (status, len(body), took))

    # A captive portal or an error page is HTML and is still 200.
    if body[:15].lstrip()[:1] == b"<" or "html" in ctype.lower():
        res.add("bad", "live feed shape", "this is a web page, not a feed")
        return None
    if len(body) < 200:
        res.add("bad", "live feed size", "%d bytes is too small to be a feed" % len(body))
        return None
    try:
        feed = parse_feed(body)
    except Exception as e:
        res.add("bad", "live feed parse", "malformed protobuf: %s" % e)
        return None

    now = int(time.time())
    ts = feed["header_ts"]
    if not ts:
        res.add("warn", "live feed timestamp", "the feed carries no header timestamp")
    else:
        age = now - ts
        if age < 0:
            res.add("warn", "live feed timestamp",
                    "dated %ds in the FUTURE, so one of the two clocks is wrong" % -age)
        elif age <= 120:
            res.add("ok", "live feed is fresh", "%ds old" % age)
        elif age <= 600:
            res.add("warn", "live feed is late", "%d minutes old" % (age // 60))
        else:
            res.add("bad", "live feed is stale",
                    "%d minutes old. The numbers on the screen are from then, "
                    "not from now" % (age // 60))

    # An independent witness. The header timestamp is written by whoever
    # builds the feed; Last-Modified is written by the server that serves it.
    # When those two disagree by a lot, something in between is holding a
    # copy, and that is a different fault from a publisher that has stopped.
    lm = headers.get("last-modified")
    if lm and ts:
        try:
            import email.utils
            lmts = int(email.utils.parsedate_to_datetime(lm).timestamp())
            drift = abs(lmts - ts)
            if drift > 300:
                res.add("warn", "feed and server disagree",
                        "the body says %ds ago, the server says %ds ago, so "
                        "something between them is serving a copy"
                        % (now - ts, now - lmts))
            else:
                res.add("ok", "server agrees with the body", "within %ds" % drift)
        except Exception:
            pass

    # Stalled: the same header timestamp handed out again, some time later.
    prev = state.get("rt")
    if prev and ts and prev.get("header_ts") == ts:
        gap = int(time.time() - prev.get("seen_at", 0))
        if gap > 90:
            res.add("bad", "live feed is stalled",
                    "the same timestamp %ds apart, so nothing is being published" % gap)
    if ts:
        state["rt"] = {"header_ts": ts, "seen_at": int(time.time()),
                       "entities": feed["entities"]}

    # Thin: a collapse in vehicle count is a fault even when everything parses.
    n = feed["entities"]
    base = state.get("rt_baseline")
    if n == 0:
        res.add("bad", "live feed is empty", "0 vehicles")
    elif base and n < max(5, base * 0.3):
        res.add("bad", "live feed is thin",
                "%d vehicles against a usual %d" % (n, base))
    elif base and n < base * 0.6:
        res.add("warn", "live feed is thin", "%d vehicles against a usual %d" % (n, base))
    else:
        res.add("ok", "live vehicles", "%d" % n)
    if n:
        state["rt_baseline"] = int(base * 0.8 + n * 0.2) if base else n

    # Misplaced: a position outside Zagreb is not a Zagreb tram.
    bad_pos = [p for p in feed["positions"]
               if not (LAT_MIN <= p[0] <= LAT_MAX and LON_MIN <= p[1] <= LON_MAX)]
    if feed["positions"]:
        if bad_pos:
            res.add("bad", "vehicles off the map",
                    "%d of %d outside Zagreb, first at %.4f,%.4f"
                    % (len(bad_pos), len(feed["positions"]), bad_pos[0][0], bad_pos[0][1]))
        else:
            res.add("ok", "vehicle positions", "%d, all inside Zagreb" % len(feed["positions"]))

    # Skew: if the phone's clock is out, every departure is wrong and the
    # feed is innocent. Worth separating, because the fix is a different one.
    if feed["entity_ts"]:
        newest = max(feed["entity_ts"])
        skew = now - newest
        if abs(skew) > 900 and ts and abs(now - ts) > 900:
            res.add("warn", "clock",
                    "the phone and the feed disagree by %d minutes. Check the "
                    "phone's own clock before blaming ZET" % (abs(skew) // 60))
    return feed


def check_static(res, feed):
    """The schedule each app is holding: is it current, and does the live
    feed agree with it. This is the one that catches 'the field does not
    fit the timetable'."""
    for app, spec in CACHES.items():
        z = os.path.join(os.path.expanduser("~"), spec["dir"], "zet_gtfs.zip")
        if not os.path.exists(z):
            res.add("ok", "%s schedule" % app, "no cached copy yet")
            continue
        age_h = (time.time() - os.path.getmtime(z)) / 3600.0
        try:
            with zipfile.ZipFile(z) as zf:
                names = zf.namelist()
                if "trips.txt" not in names:
                    res.add("bad", "%s schedule" % app, "the zip has no trips.txt")
                    continue
                ymd = time.strftime("%Y%m%d")
                covered = None
                if "calendar.txt" in names:
                    covered = False
                    head = None
                    for raw in zf.open("calendar.txt"):
                        line = raw.decode("utf-8", "replace").strip()
                        if head is None:
                            head = [c.strip() for c in line.split(",")]
                            continue
                        row = dict(zip(head, line.split(",")))
                        if row.get("start_date", "0") <= ymd <= row.get("end_date", "9"):
                            covered = True
                            break
                trip_ids = set()
                head = None
                for raw in zf.open("trips.txt"):
                    line = raw.decode("utf-8", "replace").strip()
                    if head is None:
                        head = [c.strip() for c in line.split(",")]
                        continue
                    row = dict(zip(head, line.split(",")))
                    if row.get("trip_id"):
                        trip_ids.add(row["trip_id"])
        except zipfile.BadZipFile:
            res.add("bad", "%s schedule" % app, "the cached zip is not a zip")
            continue
        except Exception as e:
            res.add("bad", "%s schedule" % app, "unreadable: %s" % e)
            continue

        if covered is False:
            res.add("bad", "%s schedule expired" % app,
                    "no service period in it covers today. Refresh it")
        elif age_h > 24 * 8:
            res.add("warn", "%s schedule age" % app, "%d days old" % (age_h / 24))
        else:
            res.add("ok", "%s schedule" % app,
                    "%d trips, %d hours old" % (len(trip_ids), age_h))

        # The agreement check. Live trip ids that the held schedule has never
        # heard of mean the two are from different builds, and every lookup
        # against them silently misses.
        if feed and feed["trip_ids"] and trip_ids:
            live = set(feed["trip_ids"])
            miss = live - trip_ids
            pct = 100.0 * len(miss) / len(live)
            if pct >= 50:
                res.add("bad", "%s does not fit the field" % app,
                        "%.0f%% of live trips are not in this schedule, so the two "
                        "are different builds" % pct)
            elif pct >= 10:
                res.add("warn", "%s partly fits the field" % app,
                        "%.0f%% of live trips are unknown to it" % pct)
            else:
                res.add("ok", "%s fits the field" % app,
                        "%.0f%% of live trips unknown, which is normal churn" % pct)


def check_reachable(res):
    """The static tap itself, without downloading forty megabytes."""
    import urllib.request
    req = urllib.request.Request(STATIC_URL, method="HEAD",
                                 headers={"User-Agent": UA})
    try:
        with urllib.request.urlopen(req, timeout=20) as r:
            ln = r.headers.get("Content-Length")
            res.add("ok", "schedule tap", "%d%s" % (r.status,
                    ", %s bytes" % ln if ln else ""))
    except Exception as e:
        res.add("warn", "schedule tap", "no answer to a HEAD: %s" % e)


# ---------------------------------------------------------------------------
# refresh
# ---------------------------------------------------------------------------

def refresh(only=None):
    import shutil
    home = os.path.expanduser("~")
    removed, kept, freed = 0, 0, 0
    for app, spec in CACHES.items():
        if only and app != only:
            continue
        base = os.path.join(home, spec["dir"])
        if not os.path.isdir(base):
            continue
        for name in spec["files"]:
            p = os.path.join(base, name)
            if os.path.isfile(p):
                freed += os.path.getsize(p)
                os.remove(p)
                removed += 1
        for name in spec["dirs"]:
            p = os.path.join(base, name)
            if os.path.isdir(p):
                for root, _, files in os.walk(p):
                    for f in files:
                        freed += os.path.getsize(os.path.join(root, f))
                        removed += 1
                shutil.rmtree(p, ignore_errors=True)
        kept += sum(1 for k in spec["keep"] if os.path.exists(os.path.join(base, k)))
    st = _state()
    st.pop("rt", None)
    _save_state(st)
    return removed, kept, freed


# ---------------------------------------------------------------------------

COLOURS = {"ok": "\033[1;32m", "warn": "\033[38;5;214m", "bad": "\033[1;31m"}
OFF = "\033[0m"
MARK = {"ok": "ok  ", "warn": "look", "bad": "FAIL"}


def main(argv):
    cmd = argv[1] if len(argv) > 1 else "check"
    tty = sys.stdout.isatty()

    def paint(level, text):
        return (COLOURS[level] + text + OFF) if tty else text

    if cmd == "refresh":
        removed, kept, freed = refresh()
        print("  %s  %d cached files thrown away, %.1f MB"
              % (paint("ok", "refreshed"), removed, freed / 1048576.0))
        print("  %d keys, indexes and stored timetables left alone" % kept)
        print("  each app rebuilds its schedule the next time it starts")
        if "--check" not in argv:
            return 0
        print("")

    res = Result()
    state = _state()
    feed = check_live(res, state)
    check_static(res, feed)
    check_reachable(res)
    _save_state(state)

    print("")
    # Stacked, like the key tester, for the same reason: a phone terminal
    # is about fifty characters and a feed error arrives longer than that.
    import textwrap
    for level, name, detail in res:
        print("  %s  %s" % (paint(level, MARK[level]), name))
        for chunk in textwrap.wrap(detail, 44, break_long_words=True):
            print("        %s" % chunk)
    print("")
    print("  %d checks, %d faults, %d worth a look"
          % (len(res), res.bad, res.warn))
    if res.bad:
        print("  a refresh is the first thing to try:  maha-commute refresh")
    print("")
    return 1 if res.bad else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
MAHA_STREAM_7c1a
}

maha_emit_keytest() {
  cat <<'MAHA_KEYTEST_7c1a'
#!/usr/bin/env python3
"""keytest.py, written by the MAHA COMMUTE installer.

    python keytest.py            test every key this phone holds
    python keytest.py --file F   also read keys out of a note
    python keytest.py --quiet    one line per key

WHAT THIS IS FOR

`keyring.md` says never test a key speculatively: use the first key not
known dead and let a real request find out. That rule is about the app's
normal running. This is the one place it does not apply, because being
asked "is this key good" IS the job here, and it is asked by hand.

The question actually being asked is never "does the key work". It is one
of five, and they need different answers and different fixes:

    is it a key at all          shape, before a single call is made
    is it accepted              the credential itself
    is the API turned on        a good key on a project with that API off
    is it restricted            a browser key called from a server. This is
                                the one that looks like a dead key and is not
    has the money run out       billing off, or the cap reached

The last one is the reason this exists, and it needs saying plainly:
**neither Google API has an endpoint that reports a balance.** No call
returns how much credit is left. What the wire does say, exactly, is
whether billing is switched off, whether a cap has been hit, and whether
the request was throttled. Anything beyond that is in the Cloud console
and nowhere else, and a tester that claims otherwise is guessing.

NO KEY IS EVER PRINTED. Not in full, not redacted. Each is named by its
prefix, its length and four characters of its hash, which is enough to
tell two keys apart and useless to anybody who reads it. Redaction is
what leaked a key once already: a pattern that recognises secrets is safe
for extraction, where an unknown format fails closed, and unsafe for
redaction, where an unknown format fails open and prints.
"""

import hashlib
import json
import os
import re
import sys
import time
import urllib.error
import urllib.request

APPHOME = os.path.join(os.path.expanduser("~"), ".maha.commute")
UA = "maha.commute-keytest/1 (+https://github.com/markoboskoauroville/MAHA_COMMUTE)"

# Both Google formats. A filter written for AIza alone finds nothing in a
# file full of AQ. keys, and Google has changed this once already, so a
# third format should be assumed to be coming.
KEY_SHAPES = [
    ("google", re.compile(r"AIza[A-Za-z0-9_-]{30,}")),
    ("google", re.compile(r"AQ\.[A-Za-z0-9_.-]{20,}")),
]

# Where each app keeps the key it is actually using. Read so the tester can
# say "the app is not using the key you think it is", which is its own
# whole class of confusion.
APP_KEYFILES = [
    ("shared store", os.path.join(APPHOME, "keys", "google-api.txt")),
    ("day.commute", os.path.expanduser("~/.commute/google-api.txt")),
    ("night.commute", os.path.expanduser("~/.nightcommute/gmaps-api.txt")),
    ("all.commute", os.path.expanduser("~/.all.commute/google-api.txt")),
    ("all.commute gemini", os.path.expanduser("~/.all.commute/gemini-api.txt")),
]

STREETVIEW = ("https://maps.googleapis.com/maps/api/streetview/metadata"
              "?location=45.8131,15.9775&key=%s")
GEOCODE = ("https://maps.googleapis.com/maps/api/geocode/json"
           "?address=Zagreb&key=%s")
GEMINI = "https://generativelanguage.googleapis.com/v1beta/models"

TTY = sys.stdout.isatty()
C = {"ok": "\033[1;32m", "warn": "\033[38;5;214m", "bad": "\033[1;31m",
     "dim": "\033[0;90m", "key": "\033[1;37m", "off": "\033[0m"}
LEVEL_RANK = {"ok": "ok", "warn": "warn", "bad": "bad", "dim": "ok"}
if not TTY:
    C = {k: "" for k in C}


def name_of(key):
    """A key named without being shown. Prefix, length, and four characters
    of a hash: enough to tell two apart, useless to anybody reading it."""
    fp = hashlib.sha256(key.encode()).hexdigest()[:4]
    prefix = key[:4] if key.startswith("AIza") else key[:3]
    return "%s\u2026 %d chars, fp %s" % (prefix, len(key), fp)


def find_keys(text):
    """Keys out of a handwritten note. The file is a working note with
    dates, account names, the word CANCELLED and URLs carrying tracking
    tokens that are the right length and the wrong thing. Shape takes the
    keys and leaves the prose."""
    out = []
    for _provider, rx in KEY_SHAPES:
        for m in rx.finditer(text):
            k = m.group(0).rstrip(".,;:)\"'")
            if k not in out:
                out.append(k)
    return out


def _req(url, headers=None, timeout=25):
    """One place, so no call can forget the User-Agent. A provider behind
    Cloudflare answers a request without one with 403 on every endpoint,
    which looks exactly like a ring of dead keys and is nothing to do with
    the keys."""
    h = {"User-Agent": UA}
    h.update(headers or {})
    req = urllib.request.Request(url, headers=h)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, r.read(), None
    except urllib.error.HTTPError as e:
        return e.code, e.read(), None
    except Exception as e:
        return None, b"", e


def _json(body):
    try:
        return json.loads(body.decode("utf-8", "replace"))
    except Exception:
        return {}


# ---------------------------------------------------------------------------
# the probes
#
# The cheapest legitimate question in each case. Street View METADATA is
# free and is documented as free; the image is not, so the image is never
# asked for. Gemini is asked to list models, which generates nothing.
# ---------------------------------------------------------------------------

def probe_streetview(key):
    status, body, err = _req(STREETVIEW % key)
    if err:
        return ("warn", "no answer", str(err), None)
    d = _json(body)
    s = d.get("status", "")
    msg = d.get("error_message", "")
    if s in ("OK", "ZERO_RESULTS"):
        return ("ok", s, "the key is accepted for Street View", True)
    if s == "REQUEST_DENIED":
        low = msg.lower()
        if "referer" in low or "referrer" in low:
            return ("warn", "browser only",
                    "locked to a web page, so the browser map works and "
                    "anything asked from the terminal does not", False)
        if "not authorized" in low or "api is not enabled" in low or "disabled" in low:
            return ("bad", "api off",
                    "the key is good, Street View Static is off on its project",
                    False)
        if "billing" in low:
            return ("bad", "billing off",
                    "billing is not enabled on the project behind this key",
                    False)
        if "expired" in low:
            return ("bad", "expired", "the key has expired", False)
        return ("bad", "denied", msg or "no reason given", False)
    if s == "OVER_QUERY_LIMIT":
        return ("bad", "over cap",
                "the cap is reached. The key is valid and refused until it "
                "resets or is raised", False)
    if s == "INVALID_REQUEST":
        return ("warn", "invalid request", "the probe is wrong, not the key", None)
    return ("warn", s or "http %s" % status, msg or "unexpected", None)


def probe_geocode(key):
    """A second Google API on the same key. Two APIs answering differently
    is what separates 'this key is dead' from 'this one API is switched
    off', and that is a different afternoon's work to fix."""
    status, body, err = _req(GEOCODE % key)
    if err:
        return ("warn", "no answer", str(err), None)
    d = _json(body)
    s = d.get("status", "")
    msg = d.get("error_message", "")
    if s in ("OK", "ZERO_RESULTS"):
        return ("ok", s, "accepted for Geocoding too", True)
    if s == "REQUEST_DENIED":
        low = msg.lower()
        if "referer" in low or "referrer" in low:
            return ("warn", "browser only", "same restriction here", False)
        if "not authorized" in low or "disabled" in low:
            return ("warn", "api off",
                    "Geocoding is off on this project, which may be deliberate",
                    False)
        if "billing" in low:
            return ("bad", "billing off", "billing is not enabled", False)
        return ("warn", "denied", msg or "no reason given", False)
    if s == "OVER_QUERY_LIMIT":
        return ("bad", "over cap", "the cap has been reached", False)
    return ("warn", s or "http %s" % status, msg or "unexpected", None)


def probe_gemini(key):
    status, body, err = _req(GEMINI, headers={"x-goog-api-key": key})
    if err:
        return ("warn", "no answer", str(err), None)
    d = _json(body)
    if status == 200:
        models = d.get("models", [])
        names = [m.get("name", "").replace("models/", "") for m in models]
        img = [n for n in names if "image" in n]
        detail = "%d models" % len(names)
        if img:
            detail += ", image models present"
        return ("ok", "accepted", detail, True)
    e = d.get("error", {})
    msg = (e.get("message") or "").strip()
    reason = ""
    for det in e.get("details", []) or []:
        if det.get("reason"):
            reason = det["reason"]
            break
    if status == 429 or reason == "RESOURCE_EXHAUSTED":
        # The one that gets lost, and losing it burns working keys.
        return ("warn", "429, throttled",
                "valid and rate limited. This is NOT a dead key and must "
                "never be condemned for it", True)
    if status == 400:
        return ("bad", "invalid key", msg or "rejected", False)
    if status == 403:
        low = msg.lower()
        if "billing" in low:
            return ("bad", "billing off", msg, False)
        if "disabled" in low or "has not been used" in low or reason == "SERVICE_DISABLED":
            return ("bad", "api off",
                    "the Generative Language API is off on this project", False)
        return ("bad", "refused", msg or "403", False)
    if status == 401:
        # Measured 31.8.2026 with a real AQ. key whose last four characters
        # were changed. A malformed key in this format is not read as a bad
        # key but as a bad OAuth token, so the answer is 401 and not 400.
        # The status mapping says 401 is a dead credential, so it is named
        # as one rather than left as a bare number.
        return ("bad", "not accepted", "the credential was refused outright", False)
    if status == 404:
        return ("warn", "404", "the probe URL is wrong, not the key", None)
    return ("warn", "http %s" % status, msg or "unexpected", None)


# ---------------------------------------------------------------------------

WIDTH = 42


def line(level, label, verdict, detail):
    """A phone terminal is about fifty characters and the rule is that
    nothing goes off the screen. Google's own refusals arrive three lines
    long with two URLs in them, so the row is STACKED rather than having
    its columns narrowed: verdict and label on one line, the reason
    underneath, wrapped. Narrowing the columns would not remove the
    clipping, it would only move it to a different word."""
    import textwrap
    # The verdict column is sized to the longest verdict there is, not to a
    # number that looked about right. At nine it clipped "not a maps key" to
    # "not a map", which is a word cut to fit a layout instead of a layout
    # sized to its words.
    print("     %s%-14s%s %s%s%s"
          % (C[level], verdict[:14], C["off"], C["key"], label, C["off"]))
    # A URL in a wrapped message is a single unbreakable word that is
    # longer than the line, so wrapping alone cannot hold the promise.
    # The URLs are dropped: the sentence carries the meaning and the link
    # is not something anybody follows from a phone terminal.
    d = (detail or "").split(" Learn more")[0]
    d = re.sub(r"https?://\S+", "", d)
    d = re.sub(r"\s+", " ", d).strip().rstrip(":").strip()
    for chunk in textwrap.wrap(d, WIDTH, break_long_words=True) or []:
        print("       %s%s%s" % (C["dim"], chunk, C["off"]))


def test_key(key, quiet=False):
    print("\n  %s%s%s" % (C["key"], name_of(key), C["off"]))
    results = {}
    # An AQ. key is a Generative Language credential and Maps has never
    # heard of it. Its refusal there is the correct answer to the wrong
    # question, so it is reported quietly. A tester that paints an expected
    # answer red teaches the person to ignore red.
    gemini_shaped = key.startswith("AQ.")
    for label, fn in (("street view", probe_streetview),
                      ("geocoding", probe_geocode),
                      ("gemini", probe_gemini)):
        level, verdict, detail, good = fn(key)
        if gemini_shaped and label in ("street view", "geocoding") and not good:
            level, verdict = "dim", "not maps"
            detail = "expected: the AQ. format is a Gemini credential"
        results[label] = (level, verdict, good)
        if not quiet:
            line(level, label, verdict, detail)
        time.sleep(0.2)

    maps_ok = results["street view"][2] or results["geocoding"][2]
    gem_ok = results["gemini"][2]
    restricted = any(r[1] == "browser only" for r in results.values())

    if gem_ok and not maps_ok:
        v, lvl = "a Gemini key", "ok"
    elif maps_ok and not gem_ok:
        v, lvl = "a Maps key", "ok"
    elif maps_ok and gem_ok:
        v, lvl = "works for both Maps and Gemini", "ok"
    elif restricted:
        v, lvl = "browser only, locked to a referrer", "warn"
    else:
        v, lvl = "nothing accepted it", "bad"
    print("     %s%-14s%s %s%s%s" % (C[lvl], "verdict", C["off"], C["key"], v, C["off"]))
    return LEVEL_RANK.get(lvl, lvl)


def main(argv):
    keys = []
    seen = set()
    sources = {}

    for label, path in APP_KEYFILES:
        if os.path.exists(path):
            try:
                with open(path, encoding="utf-8", errors="replace") as f:
                    for k in find_keys(f.read()):
                        if k not in seen:
                            seen.add(k)
                            keys.append(k)
                        sources.setdefault(k, []).append(label)
            except Exception:
                pass

    if "--file" in argv:
        p = argv[argv.index("--file") + 1]
        with open(p, encoding="utf-8", errors="replace") as f:
            text = f.read()
        found = find_keys(text)
        print("\n  %s%d keys found by shape in %s%s"
              % (C["dim"], len(found), os.path.basename(p), C["off"]))
        for k in found:
            if k not in seen:
                seen.add(k)
                keys.append(k)
            sources.setdefault(k, []).append("the note")

    if not keys:
        print("\n  no keys on this phone yet. maha-commute key, then p, pastes one.\n")
        return 1

    print("\n  %sKEY TESTER%s  %d keys, none is printed"
          % (C["key"], C["off"], len(keys)))
    print("  %sthe cheapest question each provider has,%s" % (C["dim"], C["off"]))
    print("  %snothing generated, nothing billed%s" % (C["dim"], C["off"]))

    counts = {"ok": 0, "warn": 0, "bad": 0}
    for k in keys:
        lvl = test_key(k, "--quiet" in argv)
        counts[lvl] += 1
        where = sources.get(k, [])
        if where:
            print("     %s%-14s %s%s" % (C["dim"], "held by",
                                        ", ".join(where), C["off"]))

    # Which key each app is really using. An app quietly holding a different
    # key from the one just tested is its own class of confusion, and it is
    # invisible unless somebody compares them.
    print("\n  %swhat each app is actually holding%s" % (C["key"], C["off"]))
    shared = None
    for label, path in APP_KEYFILES:
        if not os.path.exists(path):
            print("     %s%-20s none%s" % (C["dim"], label, C["off"]))
            continue
        with open(path, encoding="utf-8", errors="replace") as f:
            found = find_keys(f.read())
        if not found:
            print("     %s%-20s a file with no key shape in it%s"
                  % (C["warn"], label, C["off"]))
            continue
        fp = hashlib.sha256(found[0].encode()).hexdigest()[:4]
        if label == "shared store":
            shared = fp
            note = ""
        elif shared and fp != shared and "gemini" not in label:
            note = "  differs from the shared store"
        else:
            note = ""
        print("     %-20s fp %s%s" % (label, fp, note))

    print("\n  %d good, %d worth a look, %d refused"
          % (counts["ok"], counts["warn"], counts["bad"]))
    print("  %sno Google API reports a balance. Billing off," % C["dim"])
    print("  a cap reached and throttling are visible above.")
    print("  What is left to spend is only in the console.%s\n" % C["off"])
    return 0 if counts["bad"] == 0 else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))
MAHA_KEYTEST_7c1a
}

maha_emit_uninstall() {
  cat <<'MAHA_UNINST_7c1a'
#!/data/data/com.termux/files/usr/bin/bash
# uninstall.sh, written by the MAHA COMMUTE installer.
#
#   maha-commute uninstall        the panel, decide item by item
#   maha-commute uninstall --all  everything, still asks twice
#
# WHAT MAKES AN UNINSTALLER HARD IS NOT DELETING. It is knowing what is
# there. These apps were installed by hand, one at a time, over months,
# under names that have since changed, so nothing here assumes: every path
# is looked for on disk and only what is actually found is listed, with its
# size, before a single question is asked.
#
# It also sweeps up what earlier versions left behind. night.commute was
# once called nightram and once nightcommute, v1 of this umbrella installed
# a command called commute, and each of those leaves a file that no current
# installer would ever write and no current uninstaller would think to look
# for. They are listed here by name because forgetting them is how a phone
# ends up with dead commands in the PATH for a year.
#
# NOTHING IS DELETED WITHOUT THE WORD. The full wipe asks for a typed word,
# not a keypress, because a keypress is what a thumb does by accident.

. "$HOME/.maha.commute/env.sh" 2>/dev/null || {
  BIN="${PREFIX:-/data/data/com.termux/files/usr}/bin"
  APPHOME="$HOME/.maha.commute"
  MAHA_APPS="day|day.commute|.commute|v13|8082|the daytime ride|commute_server.py
night|night.commute|.nightcommute|v9|8087|the four night trams|night_server.py
all|all.commute|.all.commute|v39|8084|every station around you|all_commute_server.py"
}

if [ -t 1 ]; then
  AM="\033[38;5;214m"; SAND="\033[38;5;223m"; OK="\033[1;32m"
  BAD="\033[1;31m"; KEY="\033[1;37m"; DIM="\033[0;90m"; OFF="\033[0m"
else
  AM=""; SAND=""; OK=""; BAD=""; KEY=""; DIM=""; OFF=""
fi

ALL=0
[ "${1:-}" = "--all" ] && ALL=1

field() { printf '%s' "$1" | cut -d'|' -f"$2"; }

# Everything that could exist, in the order it should be shown. Kind is what
# it costs to lose: a command is free to reinstall, data is not, and a key
# is the one thing that cannot be rebuilt from this repository at all.
ITEMS=""
add() { ITEMS="$ITEMS$1|$2|$3
"; }

collect() {
  ITEMS=""
  local row id cmd dir
  printf '%s\n' "$MAHA_APPS" | while read -r row; do :; done
  for row in $(printf '%s\n' "$MAHA_APPS" | tr ' ' '\001'); do
    row=$(printf '%s' "$row" | tr '\001' ' ')
    id=$(field "$row" 1); cmd=$(field "$row" 2); dir="$HOME/$(field "$row" 3)"
    [ -x "$BIN/$cmd" ] && add "command" "$BIN/$cmd" "$cmd, the launcher"
    [ -d "$dir" ] && add "data" "$dir" "$cmd data, schedules and settings"
  done
  # the umbrella itself
  [ -x "$BIN/maha-commute" ]        && add "command" "$BIN/maha-commute" "the launcher"
  [ -x "$BIN/maha-commute-update" ] && add "command" "$BIN/maha-commute-update" "the updater"
  [ -d "$APPHOME/payloads" ]        && add "data" "$APPHOME/payloads" "the three cached payloads"
  [ -d "$APPHOME/backup" ]          && add "data" "$APPHOME/backup" "the folder kept before a wipe"
  [ -d "$APPHOME/keys" ]            && add "key"  "$APPHOME/keys" "the shared google key"
  [ -d "$APPHOME" ]                 && add "data" "$APPHOME" "everything else under the umbrella"
  # what earlier versions left behind, and would otherwise stay forever
  [ -x "$BIN/commute" ]      && add "old" "$BIN/commute" "the v1 launcher, replaced by maha-commute"
  [ -x "$BIN/nightram" ]     && add "old" "$BIN/nightram" "an old name for night.commute"
  [ -x "$BIN/nightcommute" ] && add "old" "$BIN/nightcommute" "an older name still"
  [ -d "$HOME/.nightram" ]   && add "old" "$HOME/.nightram" "its folder"
  printf '%s' "$ITEMS"
}

size_of() {
  if [ -d "$1" ]; then du -sh "$1" 2>/dev/null | cut -f1
  elif [ -f "$1" ]; then du -h "$1" 2>/dev/null | cut -f1
  else printf '-'; fi
}

show() {
  local n=0 kind path what colour
  printf "\n  ${AM}+--------------------------------------------+${OFF}\n"
  printf "  ${AM}|${OFF} ${KEY}%-42s${OFF} ${AM}|${OFF}\n" "UNINSTALL, what is on this phone"
  printf "  ${AM}+--------------------------------------------+${OFF}\n"
  printf '%s' "$LIST" | while IFS='|' read -r kind path what; do
    [ -z "$path" ] && continue
    n=$((n+1))
    case "$kind" in
      key)  colour="$BAD" ;;
      data) colour="$SAND" ;;
      old)  colour="$DIM" ;;
      *)    colour="$OK" ;;
    esac
    printf "  ${KEY}%2d${OFF} %b%-6s%b %-28s ${DIM}%5s${OFF}\n" \
      "$n" "$colour" "$kind" "$OFF" "$what" "$(size_of "$path")"
    printf "     ${DIM}%s${OFF}\n" "$path"
  done
  printf "\n"
}

remove_one() {
  local path="$1"
  if [ -e "$path" ]; then
    rm -rf "$path" && printf "  ${OK}gone${OFF} ${DIM}%s${OFF}\n" "$path"
  fi
}

LIST=$(collect)
if [ -z "$LIST" ]; then
  printf "\n  ${DIM}nothing of MAHA COMMUTE is on this phone.${OFF}\n\n"
  exit 0
fi

show
COUNT=$(printf '%s' "$LIST" | grep -c '|')
printf "  ${DIM}%s things, %s in total${OFF}\n" "$COUNT" \
  "$(du -shc $(printf '%s' "$LIST" | cut -d'|' -f2 | tr '\n' ' ') 2>/dev/null | tail -1 | cut -f1)"

if [ "$ALL" != 1 ]; then
  printf "\n  ${KEY}o${OFF} ${DIM}old versions only: the names earlier installs left${OFF}\n"
  printf "  ${DIM}    behind, keeping everything that works today${OFF}\n"
  printf "  ${KEY}u${OFF} ${DIM}the umbrella only, leaving the three apps working${OFF}\n"
  printf "  ${KEY}a${OFF} ${DIM}everything, all of it${OFF}\n"
  printf "  ${KEY}q${OFF} ${DIM}nothing, go back${OFF}\n"
  printf "\n  ${AM}>${OFF} "
  IFS= read -r ANS || ANS="q"
  case "$ANS" in
    u|U)
      printf "\n  ${DIM}taking away the umbrella and leaving the apps alone${OFF}\n\n"
      remove_one "$BIN/maha-commute"
      remove_one "$BIN/maha-commute-update"
      remove_one "$BIN/commute"
      remove_one "$APPHOME"
      printf "\n  ${OK}done.${OFF} ${DIM}day.commute, night.commute and all.commute${OFF}\n"
      printf "  ${DIM}still work exactly as they did before.${OFF}\n\n"
      exit 0 ;;
    o|O)
      # Only what an earlier version left. Nothing here is in use: the v1
      # launcher was replaced by maha-commute, and nightram and
      # nightcommute are names night.commute has not answered to for a
      # long time. The apps and all their data are untouched.
      printf "\n  ${DIM}clearing what earlier versions left behind${OFF}\n\n"
      gone=0
      for old in "$BIN/commute" "$BIN/nightram" "$BIN/nightcommute" \
                 "$HOME/.local/bin/nightram" "$HOME/.local/bin/nightcommute" \
                 "$HOME/.nightram"; do
        [ -e "$old" ] && { remove_one "$old"; gone=$((gone+1)); }
      done
      if [ "$gone" = 0 ]; then
        printf "  ${DIM}nothing old was found. This phone is already clean.${OFF}\n"
      else
        printf "\n  ${OK}%s removed.${OFF} ${DIM}Every working app is untouched.${OFF}\n" "$gone"
      fi
      printf "\n"
      exit 0 ;;
    a|A) : ;;
    *) printf "\n  ${DIM}nothing was changed.${OFF}\n\n"; exit 0 ;;
  esac
fi

# The second question, and it is typed. A keypress is what a thumb does by
# accident; a word is a decision. The word is in the language of the thing
# being lost rather than a bare yes.
printf "\n  ${BAD}This removes all three apps, their schedules, their${OFF}\n"
printf "  ${BAD}settings and the shared key, on this phone.${OFF}\n"
printf "\n  ${DIM}The three original installers still exist and put every${OFF}\n"
printf "  ${DIM}app back. What cannot be put back is the key, unless a${OFF}\n"
printf "  ${DIM}copy of it is somewhere else.${OFF}\n"
if [ -s "$APPHOME/keys/google-api.txt" ]; then
  printf "\n  ${SAND}the shared key is %s characters long and is about to go${OFF}\n" \
    "$(tr -d ' \r\n' < "$APPHOME/keys/google-api.txt" | wc -c | tr -d ' ')"
fi
printf "\n  ${KEY}type the word${OFF} ${SAND}wipe${OFF} ${KEY}to go ahead${OFF}\n"
printf "\n  ${AM}>${OFF} "
IFS= read -r W || W=""
if [ "$W" != "wipe" ]; then
  printf "\n  ${DIM}nothing was changed.${OFF}\n\n"
  exit 0
fi

printf "\n  ${DIM}stopping anything that is running${OFF}\n"
for proc in commute_server.py night_server.py all_commute_server.py; do
  pkill -f "$proc" 2>/dev/null && printf "  ${OK}stopped${OFF} ${DIM}%s${OFF}\n" "$proc"
done
sleep 1

printf "\n"
printf '%s' "$LIST" | cut -d'|' -f2 | while read -r p; do
  [ -n "$p" ] && remove_one "$p"
done

printf "\n  ${OK}MAHA COMMUTE is off this phone.${OFF}\n"
printf "  ${DIM}Nothing in \$PREFIX/bin is left from it:${OFF}\n"
LEFT=0
for c in maha-commute maha-commute-update commute day.commute night.commute all.commute; do
  [ -e "$BIN/$c" ] && { printf "  ${BAD}still there: %s${OFF}\n" "$BIN/$c"; LEFT=1; }
done
[ "$LEFT" = 0 ] && printf "  ${DIM}checked six names, none remains${OFF}\n"
printf "\n"
MAHA_UNINST_7c1a
}

maha_emit_update() {
  cat <<'MAHA_UPDATE_7c1a'
#!/data/data/com.termux/files/usr/bin/bash
# update.sh, written by the MAHA COMMUTE installer.
#
#   maha-commute-update              find a newer installer and run it
#   maha-commute-update <file>       use this file
#   maha-commute-update --check      say what is available, change nothing
#
# ONE UPDATER FOR ALL THREE APPS, and it updates them the way they are
# actually delivered.
#
# WHERE IT LOOKS, IN ORDER
#
#   1  a file given on the command line
#   2  github, anonymously, which is the automatic route
#   3  a newer installer already downloaded on the phone
#
# NO CREDENTIAL. MAHA_COMMUTE is public, so the fetch is a plain unsigned
# request. Nothing is stored on the phone, so there is nothing on the phone
# to lose, and an update over a borrowed connection reveals only that
# somebody asked for a public file.
#
# THE FROZEN ADDRESS IS VERSION, NOT THE INSTALLER. VERSION holds a single
# number; the installer it names carries that number at both ends. That is
# how the filename keeps its number at both ends while the updater still has
# one fixed thing to ask for.
#
#   maha-commute-update --check      say what is available, change nothing
#
# WHAT IT ADDS OVER RUNNING THE FILE BY HAND
#
#   it finds the newest one, wherever the phone put it
#   it refuses to run a file that did not arrive whole
#   it installs exactly the apps that are installed now, so an update
#     never quietly adds an app that was deliberately left out, and never
#     drops one that was wanted
#   it says the version it is coming from and going to, before it starts

set -e
. "$HOME/.maha.commute/env.sh"

if [ -t 1 ]; then
  AM="\033[38;5;214m"; SAND="\033[38;5;223m"; OK="\033[1;32m"
  BAD="\033[1;31m"; KEY="\033[1;37m"; DIM="\033[0;90m"; OFF="\033[0m"
else
  AM=""; SAND=""; OK=""; BAD=""; KEY=""; DIM=""; OFF=""
fi

CAND=""
MODE="run"

RAW="https://raw.githubusercontent.com/markoboskoauroville/MAHA_COMMUTE/main"

# What github is offering. A plain unsigned request: no token, no header,
# nothing kept afterwards.
REMOTE_V=""
if command -v curl >/dev/null 2>&1; then
  REMOTE_V=$(curl -fsSL --max-time 20 "$RAW/VERSION" 2>/dev/null | tr -cd '0-9' | head -c 6)
elif command -v wget >/dev/null 2>&1; then
  REMOTE_V=$(wget -qO- --timeout=20 "$RAW/VERSION" 2>/dev/null | tr -cd '0-9' | head -c 6)
fi

HERE="${MAHA_VERSION#v}"
if [ -n "$REMOTE_V" ]; then
  if [ "$REMOTE_V" -gt "$HERE" ] 2>/dev/null; then
    printf "\n  ${KEY}v%s is available${OFF} ${DIM}(this phone has v%s)${OFF}\n" "$REMOTE_V" "$HERE"
    if [ "$MODE" = "check" ]; then printf "\n"; exit 0; fi
    NAME="$REMOTE_V-maha_commute_v$REMOTE_V.sh"
    DL="$APPHOME/tmp/$NAME"
    mkdir -p "$APPHOME/tmp"
    printf "  ${DIM}fetching %s${OFF}\n" "$NAME"
    if curl -fsSL --max-time 300 "$RAW/$NAME" -o "$DL" 2>/dev/null ||
       wget -qO "$DL" --timeout=300 "$RAW/$NAME" 2>/dev/null; then
      CAND="$DL"
    else
      printf "  ${BAD}the fetch failed. Nothing was changed.${OFF}\n\n"; exit 1
    fi
  else
    printf "\n  ${OK}v%s is the newest there is.${OFF}\n\n" "$HERE"
    exit 0
  fi
else
  printf "\n  ${SAND}github did not answer.${OFF} ${DIM}Looking on the phone instead.${OFF}\n"
fi

# Where a phone puts a downloaded file, in the order it is likely to be.
if [ -z "$CAND" ]; then
  NEWEST=""
  for d in "$HOME/storage/downloads" "$HOME/downloads" "$HOME/Downloads" \
           "$HOME/storage/shared/Download" "$HOME"; do
    [ -d "$d" ] || continue
    for f in "$d"/*maha_commute_v*.sh; do
      [ -f "$f" ] || continue
      if [ -z "$NEWEST" ] || [ "$f" -nt "$NEWEST" ]; then NEWEST="$f"; fi
    done
  done
  CAND="$NEWEST"
fi

printf "\n  ${AM}%s${OFF}  ${KEY}MAHA COMMUTE${OFF} ${DIM}update${OFF}\n\n" "ॐ"

if [ -z "$CAND" ] || [ ! -f "$CAND" ]; then
  printf "  ${SAND}no installer found to update from.${OFF}\n\n"
  printf "  ${DIM}Download the newest %s-maha_commute_v%s.sh, then run${OFF}\n" "N" "N"
  printf "  ${DIM}maha-commute-update again. It looks in Downloads and in the${OFF}\n"
  printf "  ${DIM}home folder. A path can also be given:${OFF}\n"
  printf "  ${DIM}  maha-commute-update ~/storage/downloads/2-maha_commute_v2.sh${OFF}\n\n"
  printf "  ${DIM}nothing was changed${OFF}\n\n"
  exit 1
fi

printf "  ${DIM}found${OFF} %s\n" "$CAND"

# ---------------------------------------------------------------------
# Four checks before it is allowed to replace anything. A truncated file
# that gets installed is worse than an update that failed, because the
# failure is silent and arrives later.
# ---------------------------------------------------------------------
fails=0
sz=$(wc -c < "$CAND" | tr -d ' ')
if [ "$sz" -ge 400000 ]; then
  printf "  ${OK}ok${OFF}    ${DIM}size, %s bytes${OFF}\n" "$sz"
else
  printf "  ${BAD}FAIL${OFF}  ${DIM}size, %s bytes, too small to hold three apps${OFF}\n" "$sz"
  fails=$((fails+1))
fi
if head -1 "$CAND" | grep -q '^#!'; then
  printf "  ${OK}ok${OFF}    ${DIM}it is a script${OFF}\n"
else
  printf "  ${BAD}FAIL${OFF}  ${DIM}the first line is not a shebang${OFF}\n"; fails=$((fails+1))
fi
# The exit status is not the check. A file cut in the middle of a heredoc
# makes bash -n warn on stderr and exit zero, so the absence of output is
# what is being tested.
nout=$(bash -n "$CAND" 2>&1 || true)
if [ -z "$nout" ]; then
  printf "  ${OK}ok${OFF}    ${DIM}parses, and said nothing at all${OFF}\n"
else
  printf "  ${BAD}FAIL${OFF}  ${DIM}%s${OFF}\n" "$(printf '%s' "$nout" | head -1)"
  fails=$((fails+1))
fi
if tail -1 "$CAND" | grep -q '^# MAHA_COMMUTE_SENTINEL'; then
  printf "  ${OK}ok${OFF}    ${DIM}%s${OFF}\n" "$(tail -1 "$CAND" | cut -c3-)"
else
  printf "  ${BAD}FAIL${OFF}  ${DIM}the file ends early${OFF}\n"; fails=$((fails+1))
fi

if [ "$fails" != 0 ]; then
  printf "\n  ${BAD}%s of 4 checks failed. Nothing was changed.${OFF}\n" "$fails"
  printf "  ${DIM}download the file again${OFF}\n\n"
  exit 1
fi

NEW=$(grep -m1 '^MAHA_VERSION=' "$CAND" | cut -d'"' -f2)
printf "\n  ${DIM}this phone has${OFF} ${SAND}%s${OFF}${DIM}, the file is${OFF} ${SAND}%s${OFF}\n" \
  "$MAHA_VERSION" "${NEW:-unknown}"
if [ "$NEW" = "$MAHA_VERSION" ]; then
  printf "  ${DIM}the same version. Running it again changes nothing and is safe.${OFF}\n"
fi

# The apps that are installed now, so the update preserves the choice
# that was made rather than making it again.
PICK=""
n=0
for id in $(printf '%s\n' "$MAHA_APPS" | cut -d'|' -f1); do
  n=$((n+1))
  cmd=$(printf '%s\n' "$MAHA_APPS" | grep "^$id|" | cut -d'|' -f2)
  [ -x "$BIN/$cmd" ] && PICK="$PICK$n"
done
if [ -z "$PICK" ]; then
  printf "  ${DIM}no apps are installed, so the update installs none of them${OFF}\n"
  PICK="n"
else
  printf "  ${DIM}installed now, and kept:${OFF}"
  for id in $(printf '%s\n' "$MAHA_APPS" | cut -d'|' -f1); do
    cmd=$(printf '%s\n' "$MAHA_APPS" | grep "^$id|" | cut -d'|' -f2)
    [ -x "$BIN/$cmd" ] && printf " ${SAND}%s${OFF}" "$cmd"
  done
  printf "\n"
fi

printf "\n  ${KEY}Enter${OFF} ${DIM}install it${OFF}    ${KEY}n${OFF} ${DIM}stop, change nothing${OFF}\n"
printf "\n  ${AM}>${OFF} "
IFS= read -r ans || ans="n"
case "$ans" in [nN]*) printf "\n  ${DIM}nothing was changed${OFF}\n\n"; exit 0 ;; esac

printf "\n"
exec bash "$CAND" --offline --apps "$PICK"
MAHA_UPDATE_7c1a
}

# ---------------------------------------------------------------
# --verify, which changes nothing
#
# The honest limit of this switch: a file damaged badly enough may
# never reach this code at all. The check that matters runs on a file
# you have not run yet, and that one is tools/verify_installer.sh in
# the repository. This is the convenience version.
# ---------------------------------------------------------------
if [ "$VERIFY_ONLY" = "1" ]; then
  SELF="$0"
  printf "\n  ${KEY}verifying${OFF} ${DIM}%s${OFF}\n\n" "$SELF"
  vfail=0
  sz=$(wc -c < "$SELF" | tr -d ' ')
  if [ "$sz" -ge 400000 ]; then
    printf "  ${OK}size${OFF}      ${DIM}%s bytes${OFF}\n" "$sz"
  else
    printf "  ${BAD}size${OFF}      ${DIM}%s bytes, too small to hold three apps${OFF}\n" "$sz"
    vfail=$((vfail+1))
  fi
  if head -1 "$SELF" | grep -q '^#!'; then
    printf "  ${OK}shebang${OFF}   ${DIM}it is a script${OFF}\n"
  else
    printf "  ${BAD}shebang${OFF}   ${DIM}first line is not a shebang${OFF}\n"; vfail=$((vfail+1))
  fi
  nout=$(bash -n "$SELF" 2>&1 || true)
  if [ -z "$nout" ]; then
    printf "  ${OK}parse${OFF}     ${DIM}bash -n said nothing at all${OFF}\n"
  else
    printf "  ${BAD}parse${OFF}     ${DIM}%s${OFF}\n" "$(printf '%s' "$nout" | head -1)"
    vfail=$((vfail+1))
  fi
  if tail -1 "$SELF" | grep -q '^# MAHA_COMMUTE_SENTINEL'; then
    printf "  ${OK}sentinel${OFF}  ${DIM}the last line is present${OFF}\n"
  else
    printf "  ${BAD}sentinel${OFF}  ${DIM}the file ends early${OFF}\n"; vfail=$((vfail+1))
  fi
  printf "\n  ${DIM}4 checks, %s failed${OFF}\n\n" "$vfail"
  [ "$vfail" = "0" ] || exit 1
  exit 0
fi

# ---------------------------------------------------------------
# the banner
# ---------------------------------------------------------------
clear 2>/dev/null || true
printf "\n"
printf "  ${AM}%s${OFF}  ${KEY}MAHA COMMUTE${OFF}  ${DIM}installer %s${OFF}\n" "ॐ" "$MAHA_VERSION"
printf "  ${DIM}day, night and all of Zagreb, under one word${OFF}\n\n"

# ---------------------------------------------------------------
# is this a phone
# ---------------------------------------------------------------
step "checking Termux"
if [ -z "${PREFIX:-}" ] || [ ! -d "$BIN" ]; then
  fail_ "this installer is for Termux on Android"
  printf "\n  ${DIM}nothing was written.${OFF}\n\n"
  exit 1
fi
done_

# ---------------------------------------------------------------
# what is here already, before anything is asked
# ---------------------------------------------------------------
have() { command -v "$1" >/dev/null 2>&1; }
HAVE_PY=0;   have python  && HAVE_PY=1
have python3 && HAVE_PY=1
HAVE_OPEN=0; have termux-open-url && HAVE_OPEN=1
HAVE_FUSER=0; have fuser && HAVE_FUSER=1
HAVE_SHA=0;  have sha256sum && HAVE_SHA=1
HAVE_B64=0;  have base64 && HAVE_B64=1
REQ_MISSING=0
[ "$HAVE_PY" = "0" ] && REQ_MISSING=$((REQ_MISSING+1))

dep_row() {
  if [ "$2" = "1" ]; then
    printf "    ${OK}ok${OFF}       ${SAND}%-14s${OFF} ${DIM}%s${OFF}\n" "$1" "$3"
  elif [ "$4" = "req" ]; then
    printf "    ${BAD}MISSING${OFF}  ${SAND}%-14s${OFF} ${DIM}%s${OFF}\n" "$1" "$3"
  else
    printf "    ${DIM}absent   %-14s %s${OFF}\n" "$1" "$3"
  fi
}
printf "\n  ${KEY}what this phone has${OFF}\n"
dep_row "python"       "$HAVE_PY"    "all three servers"        "req"
dep_row "termux-api"   "$HAVE_OPEN"  "opens the page by itself" "opt"
dep_row "fuser"        "$HAVE_FUSER" "frees a busy port"        "opt"
dep_row "sha256sum"    "$HAVE_SHA"   "checks the payloads"      "opt"
dep_row "base64"       "$HAVE_B64"   "used by all.commute"      "opt"
printf "\n"

# ---------------------------------------------------------------
# which apps
#
# All three are on the screen whether they are wanted or not, and one
# already on the phone says so, so the choice is made against what is
# actually here rather than against a memory of it.
# ---------------------------------------------------------------
CHOSEN=""
if [ -n "$PICK" ]; then
  CHOSEN=$(maha_parse_pick "$PICK") || {
    printf "  ${BAD}--apps %s is not something I can read${OFF}\n\n" "$PICK"; exit 2; }
else
  while :; do
    printf "  ${KEY}which apps${OFF}\n"
    n=0
    for id in $(app_ids); do
      n=$((n+1)); row=$(app_row "$id")
      cmd=$(field "$row" 2); ver=$(field "$row" 4); desc=$(field "$row" 6)
      if is_installed "$id"; then
        printf "    ${KEY}%s${OFF}  ${SAND}%-15s${OFF} ${DIM}%-4s %s${OFF} ${OK}installed${OFF}\n" \
          "$n" "$cmd" "$ver" "$desc"
      else
        printf "    ${KEY}%s${OFF}  ${SAND}%-15s${OFF} ${DIM}%-4s %s${OFF}\n" \
          "$n" "$cmd" "$ver" "$desc"
      fi
    done
    printf "\n    ${DIM}type the numbers together, 13 for two of them${OFF}\n"
    printf "    ${KEY}Enter${OFF} ${DIM}all three${OFF}      ${KEY}n${OFF} ${DIM}none, just the menu${OFF}\n"
    printf "\n  ${AM}>${OFF} "
    IFS= read -r ANS || ANS=""
    if CHOSEN=$(maha_parse_pick "$ANS"); then break; fi
    printf "\n  ${SAND}1, 2 and 3 are the ones there are. Try again.${OFF}\n\n"
  done
fi

if [ -z "$CHOSEN" ]; then
  printf "\n  ${DIM}no apps chosen. The menu and all three payloads go on anyway,${OFF}\n"
  printf "  ${DIM}so any of them can be added later from inside commute.${OFF}\n"
else
  printf "\n  ${DIM}installing:${OFF}"
  for id in $CHOSEN; do printf " ${SAND}%s${OFF}" "$(field "$(app_row "$id")" 2)"; done
  printf "\n"
fi

# ---------------------------------------------------------------
# offline or online
# ---------------------------------------------------------------
if [ -z "$MODE" ]; then
  printf "\n  ${KEY}install mode${OFF}\n"
  printf "    ${KEY}Enter${OFF}  ${DIM}offline, use what is already here${OFF}\n"
  printf "    ${KEY}y${OFF}      ${DIM}fetch the missing dependencies first${OFF}\n"
  if [ "$REQ_MISSING" -gt 0 ]; then
    printf "\n    ${SAND}python is not here, so y is the one to press${OFF}\n"
  fi
  printf "\n  ${AM}>${OFF} "
  IFS= read -r ANS || ANS=""
  case "$ANS" in [yY]*) MODE="online" ;; *) MODE="offline" ;; esac
fi
printf "  ${DIM}mode: %s${OFF}\n\n" "$MODE"

if [ "$MODE" = "online" ]; then
  step "python runtime"
  if [ "$HAVE_PY" = "0" ]; then
    printf " ${SAND}installing${OFF}\n"
    pkg install -y python >/dev/null 2>&1 || yes | pkg install python || true
    step "python runtime"; done_
  else
    done_
  fi
  step "termux-api tools"
  if [ "$HAVE_OPEN" = "0" ]; then
    printf " ${SAND}installing${OFF}\n"
    pkg install -y termux-api >/dev/null 2>&1 || true
    step "termux-api tools"; done_
  else
    done_
  fi
  step "psmisc, for fuser"
  if [ "$HAVE_FUSER" = "0" ]; then
    printf " ${SAND}installing${OFF}\n"
    pkg install -y psmisc >/dev/null 2>&1 || true
    step "psmisc, for fuser"; done_
  else
    done_
  fi
else
  step "dependency install"; skip_
fi

# ---------------------------------------------------------------
# the google key
#
# Looked for in this order, and asked for only when every one of them
# comes back empty. The shared store wins, then any app already on the
# phone, then a file dropped in Downloads. The key is never printed.
# ---------------------------------------------------------------
step "google maps key"
mkdir -p "$KEYDIR"; chmod 700 "$KEYDIR" 2>/dev/null || true
FOUND=""
if [ -s "$KEYFILE" ]; then
  FOUND="the shared store"
else
  for c in "$HOME/.commute/google-api.txt" \
           "$HOME/.nightcommute/gmaps-api.txt" \
           "$HOME/.all.commute/google-api.txt" \
           "./google-api.txt" "./Google-maps-api.txt" \
           "$HOME/storage/downloads/google-api.txt" \
           "$HOME/storage/downloads/Google-maps-api.txt" \
           "$HOME/downloads/google-api.txt"; do
    if [ -s "$c" ]; then
      grep -v '^[[:space:]]*$' "$c" | head -1 | maha_clean_key > "$KEYFILE"
      chmod 600 "$KEYFILE"
      FOUND="$c"
      break
    fi
  done
fi
if [ -n "$FOUND" ]; then
  printf " ${OK}found${OFF} ${DIM}(%s)${OFF}\n" "$FOUND"
  ASK_KEY=0
else
  skip_
  ASK_KEY=1
fi

if [ "$ASK_KEY" = "1" ]; then
  printf "\n  ${KEY}no google maps key on this phone${OFF}\n"
  printf "  ${DIM}the apps work without one. The maps draw, the photographs${OFF}\n"
  printf "  ${DIM}and the 360 view do not. It can be added later with${OFF} ${SAND}maha-commute key${OFF}\n"
  printf "\n  ${KEY}Enter${OFF} ${DIM}carry on without it${OFF}   ${KEY}p${OFF} ${DIM}paste one now${OFF}\n"
  printf "\n  ${AM}>${OFF} "
  IFS= read -r ANS || ANS=""
  case "$ANS" in
    p|P)
      printf "\n  ${DIM}paste the key, then Enter${OFF}\n  ${AM}>${OFF} "
      IFS= read -r NEWKEY || NEWKEY=""
      NEWKEY=$(printf '%s' "$NEWKEY" | maha_clean_key)
      if [ -n "$NEWKEY" ]; then
        printf '%s\n' "$NEWKEY" > "$KEYFILE"; chmod 600 "$KEYFILE"
        printf "\n  ${OK}stored${OFF} ${DIM}%s characters${OFF}\n" "${#NEWKEY}"
      else
        printf "\n  ${DIM}nothing was pasted, carrying on without${OFF}\n"
      fi ;;
  esac
fi
printf "\n"

# ---------------------------------------------------------------
# the umbrella itself
#
# Everything under ~/.maha.commute is written before any app is
# installed, so that a failure inside one app still leaves a working
# menu behind and the other two can be added from it.
# ---------------------------------------------------------------
step "the umbrella"
mkdir -p "$APPHOME" "$PAYDIR" "$STAMPDIR" "$APPHOME/tmp"
chmod 700 "$APPHOME/tmp" 2>/dev/null || true
rm -f "$PAYDIR"/*.new 2>/dev/null || true
{
  printf '# written by the MAHA COMMUTE installer %s\n' "$MAHA_VERSION"
  printf 'MAHA_VERSION=%s\n' "$MAHA_VERSION"
  printf 'BIN="%s"\n' "$BIN"
  printf 'APPHOME="%s"\n' "$APPHOME"
  printf 'PAYDIR="%s"\n' "$PAYDIR"
  printf 'KEYDIR="%s"\n' "$KEYDIR"
  printf 'KEYFILE="%s"\n' "$KEYFILE"
  printf 'STAMPDIR="%s"\n' "$STAMPDIR"
  printf 'MAHA_APPS="%s"\n' "$MAHA_APPS"
} > "$APPHOME/env.sh.new"
mv -f "$APPHOME/env.sh.new" "$APPHOME/env.sh"
done_

step "payloads, all three"
for id in $(app_ids); do
  maha_emit_payload "$id" > "$PAYDIR/$id.payload.sh.new"
  mv -f "$PAYDIR/$id.payload.sh.new" "$PAYDIR/$id.payload.sh"
  chmod 600 "$PAYDIR/$id.payload.sh"
done
{
  for id in $(app_ids); do
    printf '%s|%s\n' "$id" "$(wc -c < "$PAYDIR/$id.payload.sh" | tr -d ' ')"
  done
} > "$PAYDIR/SIZES"
if [ "$HAVE_SHA" = "1" ]; then
  ( cd "$PAYDIR" && sha256sum day.payload.sh night.payload.sh all.payload.sh > SHA256SUMS )
fi
done_

step "the install routine"
maha_emit_install_one | install_command "$APPHOME/install-one.sh"
done_

step "the stream checker"
maha_emit_stream > "$APPHOME/stream.py.new"
mv -f "$APPHOME/stream.py.new" "$APPHOME/stream.py"
done_

step "the key tester"
maha_emit_keytest > "$APPHOME/keytest.py.new"
mv -f "$APPHOME/keytest.py.new" "$APPHOME/keytest.py"
done_

step "the updater"
maha_emit_update | install_command "$APPHOME/update.sh"
done_

step "the uninstaller"
maha_emit_uninstall | install_command "$APPHOME/uninstall.sh"
done_

step "the launcher"
maha_emit_menu | install_command "$BIN/maha-commute"
done_

step "the updater command"
printf '#!%s\nexec bash "%s/update.sh" "$@"\n' "$BIN/bash" "$APPHOME" \
  | install_command "$BIN/maha-commute-update"
done_

# v1 of this umbrella left a command called commute. Leaving it behind
# means two launchers on the PATH, one of them stale, and the stale one is
# the shorter word so it is the one that gets typed. It is replaced by a
# line that points at the new name rather than deleted, because a command
# that vanishes with no explanation reads as a broken install.
if [ -f "$BIN/commute" ] && ! grep -q 'maha-commute' "$BIN/commute" 2>/dev/null; then
  step "the old commute command"
  {
    printf '#!%s\n' "$BIN/bash"
    printf '# left by MAHA COMMUTE v2. The launcher is called maha-commute now.\n'
    printf 'printf "\\n  this is maha-commute now.\\n\\n"\n'
    printf 'exec "%s/maha-commute" "$@"\n' "$BIN"
  } | install_command "$BIN/commute"
  done_
fi

# ---------------------------------------------------------------
# the apps
# ---------------------------------------------------------------
FAILED=""
INSTALLED=""
for id in $CHOSEN; do
  if bash "$APPHOME/install-one.sh" "$id" "--$MODE"; then
    INSTALLED="$INSTALLED $id"
  else
    FAILED="$FAILED $id"
  fi
done

# ---------------------------------------------------------------
# what happened
# ---------------------------------------------------------------
printf "\n"
printf "  ${AM}%s${OFF}  ${KEY}MAHA COMMUTE${OFF}  ${DIM}%s${OFF}\n\n" "ॐ" "$MAHA_VERSION"
for id in $(app_ids); do
  row=$(app_row "$id"); cmd=$(field "$row" 2); port=$(field "$row" 5)
  if is_installed "$id"; then
    printf "    ${OK}on${OFF}   ${SAND}%-15s${OFF} ${DIM}%s, port %s${OFF}\n" \
      "$cmd" "$(stamped_version "$id")" "$port"
  else
    printf "    ${DIM}off  %-15s add it from the menu${OFF}\n" "$cmd"
  fi
done
if [ -n "$FAILED" ]; then
  printf "\n    ${BAD}did not finish:${OFF}${DIM}%s${OFF}\n" "$FAILED"
fi
printf "\n  type ${KEY}maha-commute${OFF} ${DIM}for the launcher${OFF}\n"
printf "  ${DIM}or the app name on its own: day.commute, night.commute, all.commute${OFF}\n"
printf "\n  ${DIM}the three payloads are kept in %s${OFF}\n" "$PAYDIR"
printf "  ${DIM}so any app can be added or removed later with no download${OFF}\n"
if [ "$HAVE_PY" = "0" ]; then
  printf "\n  ${SAND}python is still missing. Run this again and press y.${OFF}\n"
fi
printf "\n  ${DIM}run termux-setup-storage once, by hand, if you have not:${OFF}\n"
printf "  ${DIM}nothing can do it for you, and without it the phone's own${OFF}\n"
printf "  ${DIM}Downloads folder is not reachable from here.${OFF}\n\n"

# MAHA_COMMUTE_SENTINEL v6 5b91d75cd7ea07a1
